53	template <class TritonOp, class CudaTileOp, Signedness signedness,
54	          IntegerUpCast integerUpCast>
55	class ConvertGenericOp : public OpConversionPattern<TritonOp> {
56	private:
57	  bool approxModifier = false;
58	  bool flushToZeroModifier = false;
59	
60	public:
61	  ConvertGenericOp(TypeConverter &typeConverter, MLIRContext *context,
62	                   bool approx = false, bool flushToZero = false)
63	      : OpConversionPattern<TritonOp>(typeConverter, context),
64	        approxModifier(approx), flushToZeroModifier(flushToZero) {}
65	
66	  LogicalResult
67	  matchAndRewrite(TritonOp op, typename TritonOp::Adaptor adaptor,
68	                  ConversionPatternRewriter &rewriter) const override {
69	    return matchAndRewriteGenericOpImpl(
70	        op, adaptor.getOperands(), this->getTypeConverter(), rewriter,
71	        [&](OpBuilder &builder, Location loc, Type type,
72	            ArrayRef<Value> operands) {
73	          // For DivSIOp and RemSIOp, triton assume the LHS is positive in axis
74	          // analysis pass, see
75	          // https://github.com/triton-lang/triton/issues/7749. tileir backend
76	          // also assume the LHS is positive here for simplicity of the axis
77	          // analysis pass.
78	          // TODO: write a more general pass to analyze the all positive value.
79	          if constexpr (std::is_same_v<TritonOp, arith::DivSIOp>) {
80	            auto lhs = cuda_tile::AssumeOp::create(
81	                           rewriter, loc, operands[0],
82	                           cuda_tile::BoundedAttr::get(rewriter.getContext(), 0,
83	                                                       std::nullopt))
84	                           .getResult();
85	            auto tileSignedness = signedness == Signedness::Unsigned
86	                                      ? cuda_tile::Signedness::Unsigned
87	                                      : cuda_tile::Signedness::Signed;
88	            return CudaTileOp::create(builder, loc, type, lhs, operands[1],
89	                                      tileSignedness);
90	          } else if constexpr (std::is_same_v<TritonOp, arith::RemSIOp>) {
91	            auto tileSignedness = signedness == Signedness::Unsigned
92	                                      ? cuda_tile::Signedness::Unsigned
93	                                      : cuda_tile::Signedness::Signed;
94	            auto lhs = cuda_tile::AssumeOp::create(
95	                           rewriter, loc, operands[0],
96	                           cuda_tile::BoundedAttr::get(rewriter.getContext(), 0,
97	                                                       std::nullopt))
98	                           .getResult();
99	            return CudaTileOp::create(builder, loc, type, lhs, operands[1],
100	                                      tileSignedness);
101	          } else if constexpr (std::is_same_v<TritonOp, arith::DivSIOp> ||
102	                               std::is_same_v<TritonOp, arith::DivUIOp> ||
103	                               std::is_same_v<TritonOp, arith::CeilDivSIOp> ||
104	                               std::is_same_v<TritonOp, arith::CeilDivUIOp> ||
105	                               std::is_same_v<TritonOp, arith::FloorDivSIOp>) {
106	            assert(operands.size() == 2 && "expect two operands for divi");
107	            auto rounding = cuda_tile::RoundingMode::ZERO;
108	            if (std::is_same_v<TritonOp, arith::CeilDivSIOp> ||
109	                std::is_same_v<TritonOp, arith::CeilDivUIOp>)
110	              rounding = cuda_tile::RoundingMode::POSITIVE_INF;
111	            else if (std::is_same_v<TritonOp, arith::FloorDivSIOp>)
112	              rounding = cuda_tile::RoundingMode::NEGATIVE_INF;
113	            auto tileSignedness = signedness == Signedness::Unsigned
114	                                      ? cuda_tile::Signedness::Unsigned
115	                                      : cuda_tile::Signedness::Signed;
116	            return CudaTileOp::create(builder, loc, type, operands[0],
117	                                      operands[1], tileSignedness, rounding);
118	          } else if constexpr (std::is_same_v<TritonOp, arith::AddFOp> ||
119	                               std::is_same_v<TritonOp, arith::MulFOp> ||
120	                               std::is_same_v<TritonOp, arith::SubFOp>) {
121	            assert(operands.size() == 2 &&
122	                   "expect two operands for add/mul/sub");
123	            bool isF32 = getElementTypeOrSelf(op.getResult().getType()).isF32();
124	            bool ftzModifier = (this->flushToZeroModifier && isF32);
125	            return CudaTileOp::create(
126	                builder, loc, type, operands[0], operands[1],
127	                cuda_tile::RoundingMode::NEAREST_EVEN, ftzModifier);
128	          } else if constexpr (std::is_same_v<TritonOp, math::FmaOp>) {
129	            assert(operands.size() == 3 && "expect two operands for fma");
130	            bool isF32 = getElementTypeOrSelf(op.getResult().getType()).isF32();
131	            bool ftzModifier = (this->flushToZeroModifier && isF32);
132	            return CudaTileOp::create(
133	                builder, loc, type, operands[0], operands[1], operands[2],
134	                cuda_tile::RoundingMode::NEAREST_EVEN, ftzModifier);
135	          } else if constexpr (std::is_same_v<TritonOp, arith::DivFOp>) {
136	            assert(operands.size() == 2 && "expect two operands for div");
137	            bool isF32 = getElementTypeOrSelf(op.getResult().getType()).isF32();
138	            auto rounding = cuda_tile::RoundingMode::NEAREST_EVEN;
139	            if (isF32) {
140	              rounding = cuda_tile::RoundingMode::FULL;
141	              if (this->approxModifier)
142	                rounding = cuda_tile::RoundingMode::APPROX;
143	            }
144	            bool ftzModifier = (this->flushToZeroModifier && isF32);
145	            return CudaTileOp::create(builder, loc, operands[0], operands[1],
146	                                      rounding, ftzModifier);
147	          } else if constexpr (std::is_same_v<TritonOp,
148	                                              triton::PreciseDivFOp>) {
149	            // Lower a precise div operation. The ftz flag will not
150	            // have any effect.
151	            return CudaTileOp::create(builder, loc, operands[0], operands[1],
152	                                      cuda_tile::RoundingMode::NEAREST_EVEN);
153	          } else if constexpr (std::is_same_v<TritonOp, math::ExpOp>) {
154	            assert(operands.size() == 1 && "expect single operand for exp");
155	                return CudaTileOp::create(builder, loc, operands[0]);
156	          } else if constexpr (std::is_same_v<TritonOp, math::Exp2Op>) {
157	            assert(operands.size() == 1 && "expect single operand for ex2");
158	            bool isF32 = getElementTypeOrSelf(op.getResult().getType()).isF32();
159	            bool ftzModifier = (this->flushToZeroModifier && isF32);
160	            return CudaTileOp::create(builder, loc, operands[0], ftzModifier);
161	          } else if constexpr (std::is_same_v<TritonOp, math::SqrtOp>) {
162	            assert(operands.size() == 1 && "expect single operand for sqrt");
163	            bool isF32 = getElementTypeOrSelf(op.getResult().getType()).isF32();
164	            auto rounding = cuda_tile::RoundingMode::NEAREST_EVEN;
165	            if (this->approxModifier && isF32)
166	              rounding = cuda_tile::RoundingMode::APPROX;
167	            bool ftzModifier = (this->flushToZeroModifier && isF32);
168	            return CudaTileOp::create(builder, loc, operands[0], rounding,
169	                                      ftzModifier);
170	          } else if constexpr (std::is_same_v<TritonOp,
171	                                              triton::PreciseSqrtOp>) {
172	            // Lower a precise sqrt operation. The ftz flag will not
173	            // have any effect.
174	            return CudaTileOp::create(builder, loc, operands[0],
175	                                      cuda_tile::RoundingMode::NEAREST_EVEN);
176	          } else if constexpr (signedness != Signedness::None) {
177	            auto tileSignedness = signedness == Signedness::Unsigned
178	                                      ? cuda_tile::Signedness::Unsigned
179	                                      : cuda_tile::Signedness::Signed;
180	            return CudaTileOp::create(builder, loc, type, operands,
181	                                      tileSignedness);
182	          } else {
183	            return CudaTileOp::create(builder, loc, type, operands);
184	          }
185	        },
186	        signedness, integerUpCast);
187	  }
188	};
