46	class CudaTileConversionTarget : public ConversionTarget {
47	public:
48	  CudaTileConversionTarget(MLIRContext &context,
49	                           CudaTileTypeConverter &typeConverter)
50	      : ConversionTarget(context) {
51	
52	    addLegalDialect<cuda_tile::CudaTileDialect>();
53	    addIllegalDialect<scf::SCFDialect, cf::ControlFlowDialect,
54	                      mlir::gpu::GPUDialect, triton::TritonDialect,
55	                      ub::UBDialect>();
56	
57	    addLegalOp<ub::PoisonOp>();
58	    // barrierOp will be removed in AutoGenMemoryTokenPass
59	    addLegalOp<mlir::gpu::BarrierOp>();
60	
61	    // TODO: support these arith/math ops in cuda_tile
62	    addLegalOp<arith::IndexCastOp>();
