69	template <typename OpTy, typename DestOpTy>
70	static LogicalResult rewriteReshapeLike(const TypeConverter *typeConverter,
71	                                        OpTy op, typename OpTy::Adaptor adaptor,
72	                                        ConversionPatternRewriter &rewriter) {
73	  RankedTensorType sourceTensorType = op.getSrc().getType();
74	  RankedTensorType resultTensorType = op.getResult().getType();
75	
76	  // If source and result types are matching, those are no-ops.
77	  if (sourceTensorType == resultTensorType) {
78	    rewriter.replaceOp(op, adaptor.getSrc());
79	    return success();
80	  }
81	
82	  auto newResultType = typeConverter->convertType(resultTensorType);
83	  assert(newResultType && "failed to convert tensor type");
84	  rewriter.replaceOpWithNewOp<DestOpTy>(op, newResultType, adaptor.getSrc());
85	  return success();
86	}
87	
88	static DenseTypedElementsAttr
89	convertArithAttrToCudaTileAttr(const TypedAttr &attr,
90	                               const ShapedType &shapeType) {
91	  auto shape = shapeType.getShape();
92	  if (auto arithDense = dyn_cast<DenseElementsAttr>(attr))
93	    return cast<DenseTypedElementsAttr>(DenseElementsAttr::getFromRawBuffer(
94	        shapeType, arithDense.getRawData()));
95	  return cast<DenseTypedElementsAttr>(
96	      DenseElementsAttr::get(shapeType, {cast<Attribute>(attr)}));
97	}
