99	class ConvertAbsFOp : public OpConversionPattern<math::AbsFOp> {
100	public:
101	  using OpConversionPattern::OpConversionPattern;
102	
103	  LogicalResult
104	  matchAndRewrite(math::AbsFOp op, OpAdaptor adaptor,
105	                  ConversionPatternRewriter &rewriter) const override {
106	    auto loc = op.getLoc();
107	    cuda_tile::TileType newResultTensorType = cast<cuda_tile::TileType>(
108	        this->getTypeConverter()->convertType(op.getResult().getType()));
109	    auto eltype = newResultTensorType.getElementType();
110	    if (eltype.getIntOrFloatBitWidth() < 16) {
111	      // f8 and f4 not directly supported, upcast to fp16 and downcast after
112	      cuda_tile::TileType f16TensorType = cuda_tile::TileType::get(
113	          newResultTensorType.getShape(), rewriter.getF16Type());
114	      auto upcast = cuda_tile::FToFOp::create(rewriter, loc, f16TensorType,
115	                                              adaptor.getOperand());
116	      auto absop = cuda_tile::AbsFOp::create(rewriter, loc, upcast);
117	      rewriter.replaceOpWithNewOp<cuda_tile::FToFOp>(op, newResultTensorType,
118	                                                     absop);
119	      return success();
120	    }
121	    rewriter.replaceOpWithNewOp<cuda_tile::AbsFOp>(op, adaptor.getOperand());
122	    return success();
123	  }
124	};
