234	class ConvertLoadOp : public OpConversionPattern<triton::LoadOp> {
235	public:
236	  using OpConversionPattern<triton::LoadOp>::OpConversionPattern;
237	
238	  const DenseMap<Operation *, int> &numStagesMap;
239	  int computeCapability;
240	  std::optional<int> numStages;
241	  ConvertLoadOp(TypeConverter &typeConverter, MLIRContext *context,
242	                DenseMap<Operation *, int> &numStagesMap, int computeCapability,
243	                std::optional<int> numStages)
244	      : OpConversionPattern<triton::LoadOp>(typeConverter, context),
245	        numStagesMap(numStagesMap), computeCapability(computeCapability),
246	        numStages(numStages) {}
247	
248	  LogicalResult
249	  matchAndRewrite(triton::LoadOp op, typename triton::LoadOp::Adaptor adaptor,
250	                  ConversionPatternRewriter &rewriter) const override {
251	    Type retType = getTypeConverter()->convertType(op.getType());
252	    auto ctx = rewriter.getContext();
253	
254	    auto sem = cuda_tile::MemoryOrderingSemanticsAttr::get(
255	        ctx, cuda_tile::MemoryOrderingSemantics::WEAK);
256	    // There is no per op num_stages support in triton, and usually the
257	    // global-scope num_stages is meant to tune for the large load op which are
258	    // critical to performance. For small load op, we skip the num_stages hint.
259	    auto tileType = cast<cuda_tile::TileType>(retType);
260	    int64_t tileSizeInBytes =
261	        tileType.getNumElements() *
262	        (tileType.getElementType().getIntOrFloatBitWidth() / 8);
263	    std::optional<cuda_tile::OptimizationHintsAttr> optHint;
264	    if (tileSizeInBytes <= 256) {
265	      optHint = std::nullopt;
266	    } else {
267	      optHint = mlir::triton::utils::convertNumStagesToOptHint(
268	          op, ctx, numStagesMap, computeCapability, numStages);
269	    }
270	
271	    auto newLoadOp = cuda_tile::LoadPtrTkoOp::create(
272	        rewriter, op.getLoc(), retType, cuda_tile::TokenType::get(ctx), sem,
273	        /*memoryScope=*/nullptr, adaptor.getPtr(), adaptor.getMask(),
274	        adaptor.getOther(), /*token=*/nullptr, optHint.value_or(nullptr));
275	    rewriter.replaceOp(op, newLoadOp.getResult());
276	    return success();
277	  }
278	};
