325	// Helper function to create target operations (FuncOp or EntryOp)
326	template <typename TargetOp>
327	void createTargetOp(ConversionPatternRewriter &rewriter, triton::FuncOp op,
328	                    FunctionType newFunctionType,
329	                    TypeConverter::SignatureConversion &result,
330	                    int computeCapability, int numCTAInCGA,
331	                    int simtNumWarpsInCTA, int occupancy) {
332	  MLIRContext *ctx = rewriter.getContext();
333	
334	  auto newKernelName = op.getSymName();
335	
336	  TargetOp newOp;
337	  if constexpr (std::is_same_v<TargetOp, cuda_tile::EntryOp>) {
338	    llvm::StringRef archPrefix = "sm_";
339	        auto numCTAAttr =
340	            rewriter.getNamedAttr("num_cta_in_cga",
341	                                  rewriter.getI32IntegerAttr(numCTAInCGA));
342	        auto occupancyAttr =
343	            rewriter.getNamedAttr("occupancy",
344	                                  rewriter.getI32IntegerAttr(occupancy));
345	        auto hintEntry = rewriter.getNamedAttr(
346	            (archPrefix + llvm::Twine(computeCapability)).str(),
347	            DictionaryAttr::get(ctx,
348	                                {numCTAAttr, occupancyAttr}));
349	    cuda_tile::OptimizationHintsAttr optHint =
350	        cuda_tile::OptimizationHintsAttr::get(
351	            ctx, DictionaryAttr::get(ctx, {hintEntry}));
352	    newOp = cuda_tile::EntryOp::create(
353	        rewriter, op.getLoc(), StringAttr::get(ctx, newKernelName),
354	        newFunctionType, op.getArgAttrsAttr(), op.getResAttrsAttr(), optHint);
355	  } else {
356	    static_assert(std::is_same_v<TargetOp, void>, "unsupported TargetOp type");
357	  }
358	
359	  for (unsigned i = 0, e = newOp.getNumArguments(); i < e; ++i) {
360	    if (newOp.getArgAttr(i, "tt.divisibility")) {
361	      newOp.removeArgAttr(i, "tt.divisibility");
362	    }
363	  }
364	
365	  Block *oldBody = &op.getFunctionBody().front();
366	  (void)rewriter.applySignatureConversion(oldBody, result);
367	  rewriter.inlineRegionBefore(op.getBody(), newOp.getBody(),
368	                              newOp.getBody().end());
369	  rewriter.replaceOp(op, newOp);
370	}
