372	class ConvertFuncOp : public OpConversionPattern<triton::FuncOp> {
373	public:
374	  using OpConversionPattern<triton::FuncOp>::OpConversionPattern;
375	  int computeCapability;
376	  int numCTAInCGA;
377	  int simtNumWarpsInCTA;
378	  int occupancy;
379	  ConvertFuncOp(TypeConverter &typeConverter, MLIRContext *context,
380	                int computeCapability, int numCTAInCGA, int simtNumWarpsInCTA,
381	                int occupancy)
382	      : OpConversionPattern(typeConverter, context),
383	        computeCapability(computeCapability), numCTAInCGA(numCTAInCGA),
384	        simtNumWarpsInCTA(simtNumWarpsInCTA), occupancy(occupancy) {};
385	
386	  LogicalResult
387	  matchAndRewrite(triton::FuncOp op, OpAdaptor adaptor,
388	                  ConversionPatternRewriter &rewriter) const override {
389	    auto converter = getTypeConverter();
390	    FunctionType type = dyn_cast<FunctionType>(op.getFunctionType());
391	
392	    TypeConverter::SignatureConversion result(type.getNumInputs());
393	
394	    // Special treat for host tma descriptor:
395	    // We need to convert triton::TensorDescType to TileType<int> instead of
396	    // PartitionViewType, because cuda_tile does not allow view type in
397	    // signatures. Here we convert triton::TensorDescType to integer type, later
398	    // type converter will convert it to TileType<int> in the
399	    // convertSignatureArgs API.
400	    SmallVector<Type> modifiedInputs = llvm::to_vector(type.getInputs());
401	    for (auto &inType : modifiedInputs) {
402	      if (isa<triton::TensorDescType>(inType))
403	        inType = rewriter.getI32Type();
404	    }
405	
406	    SmallVector<Type, 1> newResults;
407	    if (failed(typeConverter->convertSignatureArgs(modifiedInputs, result)) ||
408	        failed(typeConverter->convertTypes(type.getResults(), newResults)) ||
409	        failed(rewriter.convertRegionTypes(&op.getFunctionBody(),
410	                                           *typeConverter, &result)))
411	      return rewriter.notifyMatchFailure(op.getLoc(),
412	                                         "typeConversion of FuncOp failed");
413	
414	    auto context = rewriter.getContext();
415	    auto newFunctionType =
416	        FunctionType::get(context, result.getConvertedTypes(), newResults);
417	
418	    createTargetOp<cuda_tile::EntryOp>(rewriter, op, newFunctionType, result,
419	                                       computeCapability, numCTAInCGA,
420	                                       simtNumWarpsInCTA, occupancy);
421	    return success();
422	    return success();
423	  }
424	};
