477	class ConvertDescriptorLoadOp
478	    : public OpConversionPattern<triton::DescriptorLoadOp> {
479	public:
480	  using OpConversionPattern<triton::DescriptorLoadOp>::OpConversionPattern;
481	
482	  const DenseMap<Operation *, int> &numStagesMap;
483	  int computeCapability;
484	  std::optional<int> numStages;
485	  ConvertDescriptorLoadOp(TypeConverter &typeConverter, MLIRContext *context,
486	                          DenseMap<Operation *, int> &numStagesMap,
487	                          int computeCapability, std::optional<int> numStages)
488	      : OpConversionPattern<triton::DescriptorLoadOp>(typeConverter, context),
489	        numStagesMap(numStagesMap), computeCapability(computeCapability),
490	        numStages(numStages) {}
491	
492	  LogicalResult
493	  matchAndRewrite(triton::DescriptorLoadOp op, OpAdaptor adaptor,
494	                  ConversionPatternRewriter &rewriter) const override {
495	
496	    auto ctx = rewriter.getContext();
497	    auto view = adaptor.getDesc();
498	
499	    auto optHint = mlir::triton::utils::convertNumStagesToOptHint(
500	        op, ctx, numStagesMap, computeCapability, numStages);
501	
502	    auto originalIndices = adaptor.getIndices();
503	
504	    SmallVector<Value> indices;
505	    SmallVector<int64_t> viewShapeVec;
506	    Type viewTy = view.getType();
507	
508	    // Handle PartitionViewType
509	    if (auto partTy = dyn_cast<cuda_tile::PartitionViewType>(viewTy)) {
510	      // For PartitionViewType, we need to divide indices by tile size
511	      auto tileSizes = partTy.getTileShape();
512	      for (size_t i = 0; i < originalIndices.size(); i++) {
513	        Value indicesWithBlockSize = originalIndices[i];
514	        cuda_tile::TileType constType =
515	            cuda_tile::TileType::get({}, rewriter.getI32Type());
516	        auto tileSizeAttr =
517	            DenseIntElementsAttr::get(constType, {tileSizes[i]});
518	        Value tileSizeOp = cuda_tile::ConstantOp::create(
519	            rewriter, op.getLoc(), constType, tileSizeAttr);
520	        indices.push_back(cuda_tile::DivIOp::create(
521	            rewriter, op.getLoc(), indicesWithBlockSize, tileSizeOp,
522	            cuda_tile::Signedness::Signed));
523	      }
524	      for (size_t i = 0; i < tileSizes.size(); i++)
525	        viewShapeVec.push_back(tileSizes[i]);
526	    } else {
527	      return rewriter.notifyMatchFailure(
528	          op.getLoc(), "expect a partition view type");
529	    }
530	
531	    auto tileShape = op.getResult().getType().getShape();
532	    auto elemTy = op.getResult().getType().getElementType();
533	    auto viewTileTy = cuda_tile::TileType::get(ctx, viewShapeVec, elemTy);
534	
535	    auto memOrder = cuda_tile::MemoryOrderingSemanticsAttr::get(
536	        ctx, cuda_tile::MemoryOrderingSemantics::WEAK);
537	    auto LoadViewOp = cuda_tile::LoadViewTkoOp::create(
538	        rewriter, op.getLoc(), viewTileTy, cuda_tile::TokenType::get(ctx),
539	        /*memory_ordering_semantics=*/memOrder,
540	        /*scope=*/nullptr, view, indices, /*token=*/nullptr,
541	        optHint.value_or(nullptr));
542	
543	    if (viewShapeVec.size() != tileShape.size()) {
544	      auto tileTy = cuda_tile::TileType::get(ctx, tileShape, elemTy);
545	      auto reshapeOp = cuda_tile::ReshapeOp::create(
546	          rewriter, op.getLoc(), tileTy, LoadViewOp.getTile());
547	      rewriter.replaceOp(op, reshapeOp.getResult());
548	      return success();
549	    }
550	
551	    rewriter.replaceOp(op, LoadViewOp.getTile());
552	    return success();
553	  }
554	};
