631	class ConvertExternElementwiseOp
632	    : public OpConversionPattern<triton::ExternElementwiseOp> {
633	public:
634	  using OpConversionPattern<triton::ExternElementwiseOp>::OpConversionPattern;
635	
636	  LogicalResult
637	  matchAndRewrite(triton::ExternElementwiseOp op, OpAdaptor adaptor,
638	                  ConversionPatternRewriter &rewriter) const override {
639	    Location loc = op.getLoc();
640	    auto symbol = op.getSymbol();
641	
642	    auto getTileType = [](Value v) {
643	      return cast<cuda_tile::TileType>(v.getType());
644	    };
645	    auto rmNearestEven = cuda_tile::RoundingModeAttr::get(
646	        rewriter.getContext(), cuda_tile::RoundingMode::NEAREST_EVEN);
647	
648	    auto splatFloat = [&](cuda_tile::TileType tileType, double value) -> Value {
649	      auto elementType = cast<FloatType>(tileType.getElementType());
650	      auto scalarAttr = rewriter.getFloatAttr(elementType, value);
651	      auto denseAttr = cast<DenseTypedElementsAttr>(
652	          DenseElementsAttr::get(tileType, scalarAttr));
653	      return cuda_tile::ConstantOp::create(rewriter, loc, tileType, denseAttr);
654	    };
655	    auto splatInt = [&](cuda_tile::TileType tileType, int64_t value) -> Value {
656	      auto elementType = cast<IntegerType>(tileType.getElementType());
657	      auto scalarAttr = rewriter.getIntegerAttr(elementType, value);
658	      auto denseAttr = cast<DenseTypedElementsAttr>(
659	          DenseElementsAttr::get(tileType, scalarAttr));
660	      return cuda_tile::ConstantOp::create(rewriter, loc, tileType, denseAttr);
661	    };
662	
663	    auto addf = [&](Value a, Value b) -> Value {
664	      return cuda_tile::AddFOp::create(rewriter, loc, a, b, rmNearestEven,
665	                                       /*flush_to_zero=*/nullptr);
666	    };
667	    auto subf = [&](Value a, Value b) -> Value {
668	      return cuda_tile::SubFOp::create(rewriter, loc, a, b, rmNearestEven,
669	                                       /*flush_to_zero=*/nullptr);
670	    };
671	    auto mulf = [&](Value a, Value b) -> Value {
672	      return cuda_tile::MulFOp::create(rewriter, loc, a, b, rmNearestEven,
673	                                       /*flush_to_zero=*/nullptr);
674	    };
675	    auto divf = [&](Value a, Value b) -> Value {
676	      return cuda_tile::DivFOp::create(rewriter, loc, a, b, rmNearestEven,
677	                                       /*flush_to_zero=*/nullptr);
678	    };
679	    auto floor = [&](Value a) -> Value {
680	      return cuda_tile::FloorOp::create(rewriter, loc, a);
681	    };
682	    auto sqrt = [&](Value a) -> Value {
683	      return cuda_tile::SqrtOp::create(rewriter, loc, a, rmNearestEven,
684	                                       /*flush_to_zero=*/nullptr);
685	    };
686	    auto exp = [&](Value a) -> Value {
687	      return cuda_tile::ExpOp::create(rewriter, loc, a);
688	    };
689	    auto cmpf = [&](cuda_tile::ComparisonPredicate pred,
690	                    cuda_tile::ComparisonOrdering ord, Value a,
691	                    Value b) -> Value {
692	      return cuda_tile::CmpFOp::create(rewriter, loc, pred, ord, a, b);
693	    };
694	    // TODO: other math func support(use extern_eltwise or impl math func)
695	    if (symbol == "__nv_acosf" || symbol == "__nv_acos") {
696	      // acos(x) = atan2(sqrt(1 - x^2), x)
697	      Value x = adaptor.getSrcs()[0];
698	      auto xType = getTileType(x);
699	      Value one = splatFloat(xType, 1.0);
700	      Value xx = mulf(x, x);
701	      Value y = sqrt(subf(one, xx));
702	      // cuda_tile.atan2 uses the conventional atan2(y, x) argument order.
703	      rewriter.replaceOpWithNewOp<cuda_tile::Atan2Op>(op, y, x);
704	      return success();
705	    } else if (symbol == "__nv_atanf" || symbol == "__nv_atan") {
706	      // atan(x) = atan2(x, 1)
707	      Value x = adaptor.getSrcs()[0];
708	      auto xType = getTileType(x);
709	      Value one = splatFloat(xType, 1.0);
710	      // cuda_tile.atan2 uses the conventional atan2(y, x) argument order.
711	      rewriter.replaceOpWithNewOp<cuda_tile::Atan2Op>(op, x, one);
712	      return success();
713	    } else if (symbol == "__nv_asinf" || symbol == "__nv_asin") {
714	      // asin(x) = atan2(x, sqrt(1 - x^2))
715	      Value x = adaptor.getSrcs()[0];
716	      auto xType = getTileType(x);
717	      Value one = splatFloat(xType, 1.0);
718	      Value xx = mulf(x, x);
719	      Value denom = sqrt(subf(one, xx));
720	      // cuda_tile.atan2 uses the conventional atan2(y, x) argument order.
721	      rewriter.replaceOpWithNewOp<cuda_tile::Atan2Op>(op, x, denom);
722	      return success();
723	    } else if (symbol == "__nv_rintf" || symbol == "__nv_rint" ||
724	               symbol == "__nv_nearbyintf" || symbol == "__nv_nearbyint") {
725	      // Round-to-nearest-even (ties to even).
726	      Value x = adaptor.getSrcs()[0];
727	      auto xType = getTileType(x);
728	      Value f = floor(x);
729	      Value d = subf(x, f); // d in [0, 1) for finite x
730	
731	      Value half = splatFloat(xType, 0.5);
732	      Value one = splatFloat(xType, 1.0);
733	      Value fPlusOne = addf(f, one);
734	
735	      Value gtHalf = cmpf(cuda_tile::ComparisonPredicate::GREATER_THAN,
736	                          cuda_tile::ComparisonOrdering::ORDERED, d, half);
737	      Value ltHalf = cmpf(cuda_tile::ComparisonPredicate::LESS_THAN,
738	                          cuda_tile::ComparisonOrdering::ORDERED, d, half);
739	
740	      // Even check without int conversion: f is even iff (f * 0.5) is integer.
741	      Value halfF = mulf(f, half);
742	      Value halfFFloor = floor(halfF);
743	      Value fIsEven =
744	          cmpf(cuda_tile::ComparisonPredicate::EQUAL,
745	               cuda_tile::ComparisonOrdering::ORDERED, halfF, halfFFloor);
746	
747	      Value tie =
748	          cuda_tile::SelectOp::create(rewriter, loc, fIsEven, f, fPlusOne);
749	      Value resLt = cuda_tile::SelectOp::create(rewriter, loc, ltHalf, f, tie);
750	      Value res =
751	          cuda_tile::SelectOp::create(rewriter, loc, gtHalf, fPlusOne, resLt);
752	      rewriter.replaceOp(op, res);
753	      return success();
754	    } else if (symbol == "__nv_isnanf" || symbol == "__nv_isnand") {
755	      // isnan(x) = unordered (x != x)
756	      Value x = adaptor.getSrcs()[0];
757	      auto resType = cast<cuda_tile::TileType>(
758	          getTypeConverter()->convertType(op.getResult().getType()));
759	      Value cond = cmpf(cuda_tile::ComparisonPredicate::NOT_EQUAL,
760	                        cuda_tile::ComparisonOrdering::UNORDERED, x, x);
761	      Value one = splatInt(resType, 1);
762	      Value zero = splatInt(resType, 0);
763	      Value res =
764	          cuda_tile::SelectOp::create(rewriter, loc, resType, cond, one, zero);
765	      rewriter.replaceOp(op, res);
766	      return success();
767	    } else if (symbol == "__nv_isinff" || symbol == "__nv_isinfd") {
768	      // IEEE isinf classification via bitcast.
769	      Value x = adaptor.getSrcs()[0];
770	      auto xType = getTileType(x);
771	      Type floatElemType = xType.getElementType();
772	      auto resType = cast<cuda_tile::TileType>(
773	          getTypeConverter()->convertType(op.getResult().getType()));
774	
775	      cuda_tile::TileType bitsType;
776	      int64_t signMask = 0;
777	      int64_t infBits = 0;
778	      if (floatElemType.isF32()) {
779	        auto shape = llvm::to_vector(xType.getShape());
780	        bitsType = cuda_tile::TileType::get(shape, rewriter.getI32Type());
781	        signMask = 0x7fffffffLL;
782	        infBits = 0x7f800000LL;
783	      } else if (floatElemType.isF64()) {
784	        auto shape = llvm::to_vector(xType.getShape());
785	        bitsType = cuda_tile::TileType::get(shape, rewriter.getI64Type());
786	        signMask = 0x7fffffffffffffffLL;
787	        infBits = 0x7ff0000000000000LL;
788	      } else {
789	        return rewriter.notifyMatchFailure(
790	            op, llvm::Twine("unsupported type for ") + symbol +
791	                    ": expected f32/f64 input");
792	      }
793	
794	      Value bits = cuda_tile::BitcastOp::create(rewriter, loc, bitsType, x);
795	      Value mask = splatInt(bitsType, signMask);
796	      Value absBits = cuda_tile::AndIOp::create(rewriter, loc, bits, mask);
797	      Value inf = splatInt(bitsType, infBits);
798	      Value cond = cuda_tile::CmpIOp::create(
799	          rewriter, loc, cuda_tile::ComparisonPredicate::EQUAL, absBits, inf,
800	          cuda_tile::Signedness::Unsigned);
801	
802	      Value one = splatInt(resType, 1);
803	      Value zero = splatInt(resType, 0);
804	      Value res =
805	          cuda_tile::SelectOp::create(rewriter, loc, resType, cond, one, zero);
806	      rewriter.replaceOp(op, res);
807	      return success();
808	    } else if (symbol == "__nv_finitef" || symbol == "__nv_isfinited") {
809	      // IEEE isfinite classification via bitcast.
810	      Value x = adaptor.getSrcs()[0];
811	      auto xType = getTileType(x);
812	      Type floatElemType = xType.getElementType();
813	      auto resType = cast<cuda_tile::TileType>(
814	          getTypeConverter()->convertType(op.getResult().getType()));
815	
816	      cuda_tile::TileType bitsType;
817	      int64_t signMask = 0;
818	      int64_t infBits = 0;
819	      if (symbol == "__nv_finitef") {
820	        // finitef is only defined for fp32 in libdevice.
821	        if (!floatElemType.isF32())
822	          return rewriter.notifyMatchFailure(op,
823	                                             "__nv_finitef expects f32 input");
824	        auto shape = llvm::to_vector(xType.getShape());
825	        bitsType = cuda_tile::TileType::get(shape, rewriter.getI32Type());
826	        signMask = 0x7fffffffLL;
827	        infBits = 0x7f800000LL;
828	      } else {
829	        // __nv_isfinited is fp64.
830	        if (!floatElemType.isF64())
831	          return rewriter.notifyMatchFailure(
832	              op, "__nv_isfinited expects f64 input");
833	        auto shape = llvm::to_vector(xType.getShape());
834	        bitsType = cuda_tile::TileType::get(shape, rewriter.getI64Type());
835	        signMask = 0x7fffffffffffffffLL;
836	        infBits = 0x7ff0000000000000LL;
837	      }
838	
839	      Value bits = cuda_tile::BitcastOp::create(rewriter, loc, bitsType, x);
840	      Value mask = splatInt(bitsType, signMask);
841	      Value absBits = cuda_tile::AndIOp::create(rewriter, loc, bits, mask);
842	      Value inf = splatInt(bitsType, infBits);
843	      Value cond = cuda_tile::CmpIOp::create(
844	          rewriter, loc, cuda_tile::ComparisonPredicate::LESS_THAN, absBits,
845	          inf, cuda_tile::Signedness::Unsigned);
846	
847	      Value one = splatInt(resType, 1);
848	      Value zero = splatInt(resType, 0);
849	      Value res =
850	          cuda_tile::SelectOp::create(rewriter, loc, resType, cond, one, zero);
851	      rewriter.replaceOp(op, res);
852	      return success();
853	    } else if (symbol == "__nv_erff" || symbol == "__nv_erf") {
854	      // High-accuracy approximation (max error ~1.5e-7):
855	      // https://stackoverflow.com/a/4578056
856	      //
857	      // t = 1 / (1 + 0.5 * |x|)
858	      // tau = t * exp(-x^2 - 1.26551223 + t*(1.00002368 + t*(0.37409196 + ...
859	      // ))) erf(x) = sign(x) * (1 - tau)
860	      Value x = adaptor.getSrcs()[0];
861	      auto xType = getTileType(x);
862	      Type floatElemType = xType.getElementType();
863	      if (!floatElemType.isF32() && !floatElemType.isF64()) {
864	        return rewriter.notifyMatchFailure(
865	            op, llvm::Twine("unsupported type for ") + symbol +
866	                    ": expected f32/f64 input");
867	      }
868	
869	      Value zero = splatFloat(xType, 0.0);
870	      Value one = splatFloat(xType, 1.0);
871	      Value half = splatFloat(xType, 0.5);
872	
873	      Value ax = cuda_tile::AbsFOp::create(rewriter, loc, x);
874	      Value t = divf(one, addf(one, mulf(half, ax)));
875	
876	      // Horner form for the nested polynomial.
877	      Value p = splatFloat(xType, 0.17087277);
878	      p = addf(splatFloat(xType, -0.82215223), mulf(t, p));
879	      p = addf(splatFloat(xType, 1.48851587), mulf(t, p));
880	      p = addf(splatFloat(xType, -1.13520398), mulf(t, p));
881	      p = addf(splatFloat(xType, 0.27886807), mulf(t, p));
882	      p = addf(splatFloat(xType, -0.18628806), mulf(t, p));
883	      p = addf(splatFloat(xType, 0.09678418), mulf(t, p));
884	      p = addf(splatFloat(xType, 0.37409196), mulf(t, p));
885	      p = addf(splatFloat(xType, 1.00002368), mulf(t, p));
886	
887	      Value negAx2 = subf(zero, mulf(ax, ax));
888	      Value expArg =
889	          addf(addf(negAx2, splatFloat(xType, -1.26551223)), mulf(t, p));
890	      Value tau = mulf(t, exp(expArg));
891	      Value erfAbs = subf(one, tau);
892	
893	      Value isNeg = cmpf(cuda_tile::ComparisonPredicate::LESS_THAN,
894	                         cuda_tile::ComparisonOrdering::ORDERED, x, zero);
895	      Value negErfAbs = subf(zero, erfAbs);
896	      Value res =
897	          cuda_tile::SelectOp::create(rewriter, loc, isNeg, negErfAbs, erfAbs);
898	      rewriter.replaceOp(op, res);
899	      return success();
900	    } else if (symbol == "__nv_ceil" || symbol == "__nv_ceilf") {
901	      rewriter.replaceOpWithNewOp<cuda_tile::CeilOp>(op, adaptor.getSrcs()[0]);
902	      return success();
903	    } else if (symbol == "__nv_pow" || symbol == "__nv_powf") {
904	      rewriter.replaceOpWithNewOp<cuda_tile::PowOp>(op, adaptor.getSrcs()[0],
905	                                                    adaptor.getSrcs()[1]);
906	      return success();
907	    } else if (symbol == "__nv_cos" || symbol == "__nv_cosf") {
908	      rewriter.replaceOpWithNewOp<cuda_tile::CosOp>(op, adaptor.getSrcs()[0]);
909	      return success();
910	    } else if (symbol == "__nv_sin" || symbol == "__nv_sinf") {
911	      rewriter.replaceOpWithNewOp<cuda_tile::SinOp>(op, adaptor.getSrcs()[0]);
912	      return success();
913	    } else if (symbol == "__nv_tan" || symbol == "__nv_tanf") {
914	      rewriter.replaceOpWithNewOp<cuda_tile::TanOp>(op, adaptor.getSrcs()[0]);
915	      return success();
916	    } else if (symbol == "__nv_exp" || symbol == "__nv_expf") {
917	      rewriter.replaceOpWithNewOp<cuda_tile::ExpOp>(op, adaptor.getSrcs()[0]);
918	      return success();
919	    } else if (symbol == "__nv_fast_expf") {
920	          rewriter.replaceOpWithNewOp<cuda_tile::ExpOp>(
921	              op, adaptor.getSrcs()[0]);
922	      return success();
923	    } else if (symbol == "__nv_exp2" || symbol == "__nv_exp2f") {
924	      rewriter.replaceOpWithNewOp<cuda_tile::Exp2Op>(op, adaptor.getSrcs()[0]);
925	      return success();
926	    } else if (symbol == "__nv_log2f" || symbol == "__nv_log2") {
927	      rewriter.replaceOpWithNewOp<cuda_tile::Log2Op>(op, adaptor.getSrcs()[0]);
928	      return success();
929	    } else if (symbol == "__nv_rsqrtf" || symbol == "__nv_rsqrt") {
930	      rewriter.replaceOpWithNewOp<cuda_tile::RsqrtOp>(op, adaptor.getSrcs()[0]);
931	      return success();
932	    } else if (symbol == "__nv_sqrtf") {
933	      rewriter.replaceOpWithNewOp<cuda_tile::SqrtOp>(
934	          op, adaptor.getSrcs()[0], cuda_tile::RoundingMode::APPROX);
935	      return success();
936	    } else if (symbol == "__nv_sqrt") {
937	      // Prefer IEEE-style rounding for fp64 sqrt.
938	      Value x = adaptor.getSrcs()[0];
939	      rewriter.replaceOp(op, sqrt(x));
940	      return success();
941	    } else if (symbol == "__nv_floorf" || symbol == "__nv_floor") {
942	      rewriter.replaceOpWithNewOp<cuda_tile::FloorOp>(op, adaptor.getSrcs()[0]);
943	      return success();
944	    } else if (symbol == "__nv_tanhf" || symbol == "__nv_tanh") {
945	      rewriter.replaceOpWithNewOp<cuda_tile::TanHOp>(
946	          op, adaptor.getSrcs()[0]);
947	      return success();
948	    } else if (symbol == "__nv_fast_tanhf") {
949	      rewriter.replaceOpWithNewOp<cuda_tile::TanHOp>(
950	          op, adaptor.getSrcs()[0]);
951	      return success();
952	    }
953	    return rewriter.notifyMatchFailure(
954	        op, llvm::Twine("unsupported extern_elementwise symbol for stable "
955	                        "cuda_tile lowering: ") +
956	                symbol +
957	                ". Please add a rewrite in ConvertExternElementwiseOp.");
958	  }
959	};
