961	class ConvertCatOp : public OpConversionPattern<triton::CatOp> {
962	public:
963	  using OpConversionPattern<triton::CatOp>::OpConversionPattern;
964	
965	  LogicalResult
966	  matchAndRewrite(triton::CatOp op, OpAdaptor adaptor,
967	                  ConversionPatternRewriter &rewriter) const override {
968	    auto resTy = cast<ShapedType>(
969	        getTypeConverter()->convertType(op.getResult().getType()));
970	
971	    // This should always be true since SameTypeOperands trait is enforced for
972	    // triton::CatOp
973	    auto lhsTy = adaptor.getLhs().getType();
974	    auto rhsTy = adaptor.getRhs().getType();
975	    assert(lhsTy == rhsTy && "Operands must have identical types");
976	
977	    // Add singleton dimension to operand type to match result rank
978	    auto reshapeToMatchResultRank = [&](Value operand) -> Value {
979	      auto operandTy = cast<ShapedType>(operand.getType());
980	      if (operandTy.getRank() == resTy.getRank())
981	        return operand;
982	      auto operandShape = llvm::to_vector(operandTy.getShape());
983	      operandShape.resize(resTy.getRank(), 1);
984	      auto newTy =
985	          operandTy.cloneWith(operandShape, operandTy.getElementType());
986	      return cuda_tile::ReshapeOp::create(rewriter, op.getLoc(), newTy,
987	                                          operand);
988	    };
989	
990	    Value lhs = reshapeToMatchResultRank(adaptor.getLhs());
991	    Value rhs = reshapeToMatchResultRank(adaptor.getRhs());
992	
993	    // Determine concatenation axis (last dimension by default)
994	    int64_t concatDim = resTy.getRank() - 1;
995	    auto lhsShape = cast<ShapedType>(lhs.getType()).getShape();
996	    for (int64_t i = 0; i < resTy.getRank(); i++)
997	      if (lhsShape[i] != resTy.getShape()[i]) {
998	        concatDim = i;
999	        break;
1000	      }
1001	
1002	    rewriter.replaceOpWithNewOp<cuda_tile::CatOp>(
1003	        op, resTy, lhs, rhs, rewriter.getI64IntegerAttr(concatDim));
1004	
1005	    return success();
1006	  }
1007	};
