1009	// Join the tensors in a new minor dimension.
1010	class ConvertJoinOp : public OpConversionPattern<triton::JoinOp> {
1011	public:
1012	  using OpConversionPattern<triton::JoinOp>::OpConversionPattern;
1013	
1014	  LogicalResult
1015	  matchAndRewrite(triton::JoinOp op, OpAdaptor adaptor,
1016	                  ConversionPatternRewriter &rewriter) const override {
1017	    Location loc = op.getLoc();
1018	
1019	    // Step1. Create a new minor dimenion using reshape.
1020	    cuda_tile::TileType lhsType =
1021	        cast<cuda_tile::TileType>(adaptor.getLhs().getType());
1022	    cuda_tile::TileType rhsType =
1023	        cast<cuda_tile::TileType>(adaptor.getRhs().getType());
1024	    assert(lhsType == rhsType &&
1025	           "expect triton cat to have same operand type for lhs and rhs");
1026	
1027	    SmallVector<int64_t> reshapedView = llvm::to_vector(lhsType.getShape());
1028	    int64_t concatDim = reshapedView.size();
1029	    reshapedView.push_back(1);
1030	    cuda_tile::TileType newLhsType =
1031	        cuda_tile::TileType::get(reshapedView, lhsType.getElementType());
1032	    auto viewOnLhs = cuda_tile::ReshapeOp::create(rewriter, loc, newLhsType,
1033	                                                  adaptor.getLhs());
1034	    auto viewOnRhs = cuda_tile::ReshapeOp::create(rewriter, loc, newLhsType,
1035	                                                  adaptor.getRhs());
1036	    reshapedView[concatDim] += reshapedView[concatDim];
1037	    cuda_tile::TileType newResType =
1038	        cuda_tile::TileType::get(reshapedView, lhsType.getElementType());
1039	
1040	    // Step2. Concat along the new minor dimension.
1041	    rewriter.replaceOpWithNewOp<cuda_tile::CatOp>(
1042	        op, newResType, viewOnLhs, viewOnRhs,
1043	        rewriter.getI64IntegerAttr(concatDim));
1044	    return success();
1045	  }
1046	};
