1064	// Helper function for common functionality between ReduceOp and ScanOp
1065	LogicalResult convertAggregationOp(Operation *op,
1066	                                   ConversionPatternRewriter &rewriter,
1067	                                   const TypeConverter *typeConverter,
1068	                                   Operation *newOp) {
1069	  SmallVector<Type> newResultTypes;
1070	  auto resConversion =
1071	      typeConverter->convertTypes(op->getResults().getType(), newResultTypes);
1072	  assert(succeeded(resConversion) && "failed to convert tensor type");
1073	
1074	  Block *oldBody = &op->getRegion(0).front();
1075	
1076	  Block *body = new Block();
1077	  SmallVector<Type> currentOperandsTy;
1078	  SmallVector<Location> locs;
1079	  // We use pair for better readability:
1080	  // [current_operand[i], prev_operand[i], current_operand[i + 1],
1081	  // prev_operand[i + 1]] while triton is: current_operand[i],
1082	  // current_operand[i + 1], prev_operand[i], prev_operand[i + 1]]
1083	  size_t numberOfArgs = oldBody->getNumArguments();
1084	  size_t half = numberOfArgs / 2;
1085	
1086	  for (int i = 0, e = numberOfArgs / 2; i < e; i++) {
1087	    BlockArgument currentBlkOperand = oldBody->getArgument(i);
1088	    locs.push_back(currentBlkOperand.getLoc());
1089	    BlockArgument preBlkOperand = oldBody->getArgument(i + half);
1090	    locs.push_back(preBlkOperand.getLoc());
1091	    currentOperandsTy.push_back(
1092	        cuda_tile::TileType::get({}, currentBlkOperand.getType()));
1093	    currentOperandsTy.push_back(
1094	        cuda_tile::TileType::get({}, preBlkOperand.getType()));
1095	  }
1096	  body->addArguments(currentOperandsTy, locs);
1097	
1098	  SmallVector<Value> blockOperands;
1099	  for (int i = 0; i < numberOfArgs / 2; i++)
1100	    blockOperands.push_back(body->getArgument(i * 2));
1101	
1102	  for (int i = 0; i < numberOfArgs / 2; i++)
1103	    blockOperands.push_back(body->getArgument(i * 2 + 1));
1104	
1105	  rewriter.inlineBlockBefore(&op->getRegion(0).front(), body, body->end(),
1106	                             blockOperands);
1107	  newOp->getRegion(0).push_back(body);
1108	  rewriter.replaceOp(op, newOp->getResults());
1109	  return success();
1110	}
