1112	class ConvertReduceOp : public OpConversionPattern<triton::ReduceOp> {
1113	public:
1114	  using OpConversionPattern<triton::ReduceOp>::OpConversionPattern;
1115	
1116	  LogicalResult
1117	  matchAndRewrite(triton::ReduceOp op, OpAdaptor adaptor,
1118	                  ConversionPatternRewriter &rewriter) const override {
1119	    SmallVector<Type> newResultTypes;
1120	    auto resConversion = getTypeConverter()->convertTypes(
1121	        op.getResults().getType(), newResultTypes);
1122	    assert(succeeded(resConversion) && "failed to convert tensor type");
1123	    Block *oldBody = &op.getRegion().front();
1124	    if (llvm::hasSingleElement(*oldBody)) {
1125	      // Fast path: This reduction is a no-op. It contains just the terminator.
1126	      auto terminator = cast<triton::ReduceReturnOp>(oldBody->getTerminator());
1127	      SmallVector<Value> repls;
1128	      for (auto it : llvm::enumerate(terminator.getResult())) {
1129	        // The returned value must be one of the bbargs. Find out which one,
1130	        // then replace the reduction op result with the respective operand.
1131	        Value v = it.value();
1132	        auto bbArg = cast<BlockArgument>(v);
1133	        unsigned operandIdx = bbArg.getArgNumber() / 2;
1134	        repls.push_back(cuda_tile::ReshapeOp::create(
1135	            rewriter, op.getLoc(), newResultTypes[it.index()],
1136	            adaptor.getSrcs()[operandIdx]));
1137	      }
1138	      rewriter.replaceOp(op, repls);
1139	      return success();
1140	    }
1141	
1142	    auto identitiesOrFailure =
1143	        getIdentitiesFromCombineOp(op.getCombineOp(), newResultTypes, rewriter);
1144	    if (failed(identitiesOrFailure))
1145	      return rewriter.notifyMatchFailure(
1146	          op, "failed to setup valid identities for combineOp");
1147	    ArrayAttr identities = *identitiesOrFailure;
1148	
1149	    auto newReduceOp = cuda_tile::ReduceOp::create(
1150	        rewriter, op.getLoc(), newResultTypes, adaptor.getOperands(),
1151	        adaptor.getAxis(), identities);
1152	
1153	    return convertAggregationOp(op, rewriter, getTypeConverter(), newReduceOp);
1154	  }
1155	};
