1257	// We will rewrite scf.while op into cuda_tile.loop op
1258	
1259	// for example:
1260	// ---------------------------------------------------------
1261	// scf.while
1262	// %results = scf.while (<while_args>) : type(<while_args>) -> type(results) { // type(<while_args>) != type(results)
1263	//     ... // `before` region code
1264	//     %cond = ...
1265	//     <condition_args> = ...
1266	//     scf.condition (%cond) <condition_args> : type(condition_args)  // type(condition_args) == type(results)
1267	// } do {
1268	//     ^bb0(after_args):  // `after_args` come from `condition_args` and type(condition_args) == type(after_args)
1269	//     ... // `after` region code
1270	//     scf.yield <yield_vals> : type(yield_vals)  // type(yield_vals) == type(while_args)
1271	// }
1272	// ---------------------------------------------------------
1273	
1274	// will be rewritten into:
1275	
1276	// ---------------------------------------------------------
1277	// %results = cuda_tile.loop iter_values(<while_args>) -> type(results) { // type(<while_args>) != type(results)
1278	//     ... // `before` region code
1279	//     %cond = ...
1280	//     <condition_args> = ...
1281	//     cuda_tile.if %cond {
1282	//         ... // `after` region code
1283	//         cuda_tile.continue <yield_vals>
1284	//     }
1285	//     cuda_tile.break <condition_args>
1286	// }
1287	// ---------------------------------------------------------
1288	
1289	// clang-format on
1290	class ConvertWhileOp : public OpConversionPattern<scf::WhileOp> {
1291	public:
1292	  using OpConversionPattern::OpConversionPattern;
1293	
1294	  LogicalResult
1295	  matchAndRewrite(scf::WhileOp whileOp, OpAdaptor adaptor,
1296	                  ConversionPatternRewriter &rewriter) const override {
1297	    Block *beforeBlock = &adaptor.getBefore().front();
1298	    Block *afterBlock = &adaptor.getAfter().front();
1299	
1300	    SmallVector<Type> resultTypes;
1301	    if (failed(typeConverter->convertTypes(whileOp->getResultTypes(),
1302	                                           resultTypes)))
1303	      return failure();
1304	
1305	    SmallVector<Type> inputTypes;
1306	    for (auto type : whileOp.getOperandTypes()) {
1307	      Type convertedType = typeConverter->convertType(type);
1308	      inputTypes.push_back(convertedType);
1309	    }
1310	
1311	    rewriter.setInsertionPoint(whileOp);
1312	
1313	    SmallVector<Location> locs(inputTypes.size(), whileOp.getLoc());
1314	    auto newLoopOp = cuda_tile::LoopOp::create(
1315	        rewriter, whileOp.getLoc(), resultTypes, adaptor.getOperands());
1316	
1317	    Block *newLoopBlock = rewriter.createBlock(
1318	        &newLoopOp.getRegion(), /*insertPt=*/{}, inputTypes, locs);
1319	
1320	    rewriter.inlineBlockBefore(beforeBlock, newLoopBlock, newLoopBlock->end(),
1321	                               newLoopBlock->getArguments());
1322	    auto conditionOp = &newLoopBlock->back();
1323	    auto castI1Op = rewriter.getRemappedValue(conditionOp->getOperand(0));
1324	
1325	    auto ifOp = cuda_tile::IfOp::create(rewriter, whileOp.getLoc(), TypeRange(),
1326	                                        castI1Op);
1327	    rewriter.createBlock(&ifOp.getThenRegion());
1328	    rewriter.createBlock(&ifOp.getElseRegion());
1329	
1330	    rewriter.setInsertionPointToStart(ifOp.getThenBlock());
1331	
1332	    SmallVector<Value> afterBlockArgs;
1333	    for (size_t i = 1; i < conditionOp->getOperands().size(); i++) {
1334	      afterBlockArgs.push_back(conditionOp->getOperands()[i]);
1335	    }
1336	
1337	    rewriter.inlineBlockBefore(afterBlock, ifOp.getThenBlock(),
1338	                               ifOp.getThenBlock()->end(), afterBlockArgs);
1339	    auto yieldOp = &ifOp.getThenBlock()->back();
1340	    SmallVector<Value> yieldOpCastArgs;
1341	    if (failed(rewriter.getRemappedValues(yieldOp->getOperands(),
1342	                                          yieldOpCastArgs)))
1343	      return failure();
1344	
1345	    cuda_tile::ContinueOp::create(rewriter, whileOp.getLoc(), yieldOpCastArgs);
1346	
1347	    SmallVector<Value> afterBlockCastArgs;
1348	    if (failed(rewriter.getRemappedValues(afterBlockArgs, afterBlockCastArgs)))
1349	      return failure();
1350	
1351	    rewriter.setInsertionPointToEnd(ifOp.getElseBlock());
1352	    cuda_tile::BreakOp::create(rewriter, whileOp.getLoc(), afterBlockCastArgs);
1353	
1354	    rewriter.setInsertionPointToEnd(newLoopBlock);
1355	    cuda_tile::BreakOp::create(rewriter, whileOp.getLoc(), afterBlockCastArgs);
1356	
1357	    rewriter.eraseOp(conditionOp);
1358	    rewriter.eraseOp(yieldOp);
1359	    rewriter.replaceOp(whileOp, newLoopOp.getResults());
1360	    return success();
1361	  }
1362	};
