1364	class ConvertForOp : public OpConversionPattern<scf::ForOp> {
1365	public:
1366	  using OpConversionPattern::OpConversionPattern;
1367	
1368	  LogicalResult
1369	  matchAndRewrite(scf::ForOp op, OpAdaptor adaptor,
1370	                  ConversionPatternRewriter &rewriter) const override {
1371	    Location loc = op.getLoc();
1372	    BlockArgument indVar = op.getBody()->getArgument(0);
1373	    if (isa<IndexType>(indVar.getType())) {
1374	      return rewriter.notifyMatchFailure(
1375	          loc, "index type is not supported in cuda tile");
1376	    }
1377	    Block *origBody = op.getBody();
1378	
1379	    auto newForOp = cuda_tile::ForOp::create(
1380	        rewriter, loc, adaptor.getLowerBound(), adaptor.getUpperBound(),
1381	        adaptor.getStep(), adaptor.getInitArgs(),
1382	        [&](OpBuilder builder, Location loc, Value indVar,
1383	            ValueRange initArgs) {
1384	          // Don't build the body here, we'll inline it right after.
1385	        });
1386	
1387	    // Apply a signature conversion on the for loop body.
1388	    cuda_tile::TileType indVarTy =
1389	        cuda_tile::TileType::get({}, indVar.getType());
1390	    TypeConverter::SignatureConversion sigConversion(
1391	        origBody->getNumArguments());
1392	    sigConversion.addInputs(0, indVarTy);
1393	    if (failed(typeConverter->convertSignatureArgs(
1394	            llvm::drop_begin(TypeRange(origBody->getArgumentTypes())),
1395	            sigConversion, /*origInputOffset=*/1)))
1396	      return failure();
1397	    Block *body = rewriter.applySignatureConversion(origBody, sigConversion);
1398	
1399	    rewriter.inlineRegionBefore(op.getRegion(), newForOp.getRegion(),
1400	                                newForOp.getRegion().begin());
1401	    rewriter.replaceOp(op, newForOp.getResults());
1402	    return success();
1403	  }
1404	};
