1406	struct ConvertCmpIOp : public OpConversionPattern<arith::CmpIOp> {
1407	public:
1408	  using OpConversionPattern<arith::CmpIOp>::OpConversionPattern;
1409	
1410	  LogicalResult
1411	  matchAndRewrite(arith::CmpIOp op, OpAdaptor adaptor,
1412	                  ConversionPatternRewriter &rewriter) const override {
1413	    // Get the arith comparison predicate
1414	    auto arithPredicate = op.getPredicate();
1415	
1416	    // Infer signedness and comparison predicate from arith predicate
1417	    cuda_tile::Signedness signedness = cuda_tile::Signedness::Signed;
1418	    cuda_tile::ComparisonPredicate comparisonPredicate;
1419	
1420	    switch (arithPredicate) {
1421	    case arith::CmpIPredicate::eq:
1422	      comparisonPredicate = cuda_tile::ComparisonPredicate::EQUAL;
1423	      break;
1424	    case arith::CmpIPredicate::ne:
1425	      comparisonPredicate = cuda_tile::ComparisonPredicate::NOT_EQUAL;
1426	      break;
1427	    case arith::CmpIPredicate::slt:
1428	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN;
1429	      break;
1430	    case arith::CmpIPredicate::sle:
1431	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN_OR_EQUAL;
1432	      break;
1433	    case arith::CmpIPredicate::sgt:
1434	      comparisonPredicate = cuda_tile::ComparisonPredicate::GREATER_THAN;
1435	      break;
1436	    case arith::CmpIPredicate::sge:
1437	      comparisonPredicate =
1438	          cuda_tile::ComparisonPredicate::GREATER_THAN_OR_EQUAL;
1439	      break;
1440	    case arith::CmpIPredicate::ult:
1441	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN;
1442	      signedness = cuda_tile::Signedness::Unsigned;
1443	      break;
1444	    case arith::CmpIPredicate::ule:
1445	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN_OR_EQUAL;
1446	      signedness = cuda_tile::Signedness::Unsigned;
1447	      break;
1448	    case arith::CmpIPredicate::ugt:
1449	      comparisonPredicate = cuda_tile::ComparisonPredicate::GREATER_THAN;
1450	      signedness = cuda_tile::Signedness::Unsigned;
1451	      break;
1452	    case arith::CmpIPredicate::uge:
1453	      comparisonPredicate =
1454	          cuda_tile::ComparisonPredicate::GREATER_THAN_OR_EQUAL;
1455	      signedness = cuda_tile::Signedness::Unsigned;
1456	      break;
1457	    default:
1458	      return rewriter.notifyMatchFailure(
1459	          op, "unsupported arith::CmpIOp predicate" +
1460	                  stringifyCmpIPredicate(arithPredicate));
1461	    }
1462	
1463	    // Upcast to i16 if necessary.
1464	    Location loc = op.getLoc();
1465	    Value lhs = upCastOrSelf(rewriter, loc, adaptor.getLhs(),
1466	                             signedness == cuda_tile::Signedness::Unsigned
1467	                                 ? Signedness::Unsigned
1468	                                 : Signedness::Signed,
1469	                             IntegerUpCast::To_I16);
1470	    Value rhs = upCastOrSelf(rewriter, loc, adaptor.getRhs(),
1471	                             signedness == cuda_tile::Signedness::Unsigned
1472	                                 ? Signedness::Unsigned
1473	                                 : Signedness::Signed,
1474	                             IntegerUpCast::To_I16);
1475	
1476	    // Replace the op with cuda_tile.cmpi.
1477	    rewriter.replaceOpWithNewOp<cuda_tile::CmpIOp>(op, comparisonPredicate, lhs,
1478	                                                   rhs, signedness);
1479	    return success();
1480	  }
1481	};
