1483	struct ConvertCmpFOp : public OpConversionPattern<arith::CmpFOp> {
1484	public:
1485	  using OpConversionPattern<arith::CmpFOp>::OpConversionPattern;
1486	
1487	  LogicalResult
1488	  matchAndRewrite(arith::CmpFOp op, OpAdaptor adaptor,
1489	                  ConversionPatternRewriter &rewriter) const override {
1490	    // Get the arith comparison predicate
1491	    auto arithPredicate = op.getPredicate();
1492	
1493	    // Infer comparison predicate and ordering from arith predicate
1494	    cuda_tile::ComparisonPredicate comparisonPredicate;
1495	    cuda_tile::ComparisonOrdering comparisonOrdering =
1496	        cuda_tile::ComparisonOrdering::ORDERED;
1497	
1498	    switch (arithPredicate) {
1499	    case arith::CmpFPredicate::OEQ:
1500	      comparisonPredicate = cuda_tile::ComparisonPredicate::EQUAL;
1501	      break;
1502	    case arith::CmpFPredicate::ONE:
1503	      comparisonPredicate = cuda_tile::ComparisonPredicate::NOT_EQUAL;
1504	      break;
1505	    case arith::CmpFPredicate::OLT:
1506	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN;
1507	      break;
1508	    case arith::CmpFPredicate::OLE:
1509	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN_OR_EQUAL;
1510	      break;
1511	    case arith::CmpFPredicate::OGT:
1512	      comparisonPredicate = cuda_tile::ComparisonPredicate::GREATER_THAN;
1513	      break;
1514	    case arith::CmpFPredicate::OGE:
1515	      comparisonPredicate =
1516	          cuda_tile::ComparisonPredicate::GREATER_THAN_OR_EQUAL;
1517	      break;
1518	    case arith::CmpFPredicate::UEQ:
1519	      comparisonPredicate = cuda_tile::ComparisonPredicate::EQUAL;
1520	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1521	      break;
1522	    case arith::CmpFPredicate::UNE:
1523	      comparisonPredicate = cuda_tile::ComparisonPredicate::NOT_EQUAL;
1524	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1525	      break;
1526	    case arith::CmpFPredicate::ULT:
1527	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN;
1528	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1529	      break;
1530	    case arith::CmpFPredicate::ULE:
1531	      comparisonPredicate = cuda_tile::ComparisonPredicate::LESS_THAN_OR_EQUAL;
1532	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1533	      break;
1534	    case arith::CmpFPredicate::UGT:
1535	      comparisonPredicate = cuda_tile::ComparisonPredicate::GREATER_THAN;
1536	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1537	      break;
1538	    case arith::CmpFPredicate::UGE:
1539	      comparisonPredicate =
1540	          cuda_tile::ComparisonPredicate::GREATER_THAN_OR_EQUAL;
1541	      comparisonOrdering = cuda_tile::ComparisonOrdering::UNORDERED;
1542	      break;
1543	    default:
1544	      return rewriter.notifyMatchFailure(
1545	          op, "unsupported arith::CmpFOp predicate" +
1546	                  stringifyCmpFPredicate(arithPredicate));
1547	    }
1548	
1549	    // Replace the op with cuda_tile.cmpf.
1550	    rewriter.replaceOpWithNewOp<cuda_tile::CmpFOp>(
1551	        op, comparisonPredicate, comparisonOrdering, adaptor.getLhs(),
1552	        adaptor.getRhs());
1553	    return success();
1554	  }
1555	};
