1691	Value wrapIntoScalarTile(OpBuilder &rewriter, Value v, unsigned attachAlignment,
1692	                         int64_t attachRange) {
1693	  auto ctx = v.getType().getContext();
1694	  auto loc = v.getLoc();
1695	  if (v.getType().isInteger(32))
1696	    v = arith::ExtSIOp::create(rewriter, loc, rewriter.getI64Type(), v)
1697	            .getResult();
1698	  auto elemType = v.getType();
1699	  auto scalarTileTy = cuda_tile::TileType::get(ctx, /*shape=*/{}, elemType);
1700	  auto scalarTile =
1701	      UnrealizedConversionCastOp::create(rewriter, loc, scalarTileTy, v)
1702	          .getResult(0);
1703	  scalarTile = cuda_tile::AssumeOp::create(
1704	                   rewriter, loc, scalarTile,
1705	                   cuda_tile::BoundedAttr::get(ctx, 0, attachRange))
1706	                   .getResult();
1707	
1708	  // we can always assume the stride are divisible by 16
1709	  // because openai has already make it into host tma api.
1710	  if (!attachAlignment)
1711	    return scalarTile;
1712	  return cuda_tile::AssumeOp::create(
1713	             rewriter, loc, scalarTile,
1714	             cuda_tile::DivByAttr::get(ctx, attachAlignment, std::nullopt,
1715	                                       std::nullopt))
1716	      .getResult();
1717	};
