1719	/// Lowering of tt.make_tensor_desc to cuda_tile.make_tensor_view.
1720	///
1721	/// Triton currently assumes that the pointer, sizes and strides are
1722	/// compatible with the TMA requirements of the target architecture.
1723	/// See commit message: https://github.com/triton-lang/triton/pull/6753
1724	/// "This does not implement: Interop for unsupported tensor descriptors on
1725	/// devices which support tensor descriptors."
1726	///
1727	/// This means that we can safely assume that the pointer and strides are
1728	/// divisible by 16. (Sizes do not have this divisibility requirement.)
1729	/// Using a pointer or strides that are not divisible by 16 will result in
1730	/// undefined behavior.
1731	/// This lowering attaches the divisibility hints to the pointer and strides.
1732	///
1733	/// It is safe to assume that shapes are in the range [0, 2^32 - 1] and
1734	/// strides are in the range [0, 2^40 - 1]
1735	/// This lowering attaches the range hints to the shapes and strides.
1736	class ConvertMakeTensorDescOp
1737	    : public OpConversionPattern<triton::MakeTensorDescOp> {
1738	public:
1739	  using OpConversionPattern<triton::MakeTensorDescOp>::OpConversionPattern;
1740	
1741	  ConvertMakeTensorDescOp(MLIRContext *context)
1742	      : OpConversionPattern<triton::MakeTensorDescOp>(context) {}
1743	
1744	  LogicalResult
1745	  matchAndRewrite(triton::MakeTensorDescOp op, OpAdaptor adaptor,
1746	                  ConversionPatternRewriter &rewriter) const override {
1747	    auto loc = op.getLoc();
1748	    auto ctx = op->getContext();
1749	    auto ptrTy = op.getBase().getType();
1750	
1751	    size_t rank = op.getShape().size();
1752	    if (rank == 0) {
1753	      return rewriter.notifyMatchFailure(
1754	          loc, "Device TMA descriptor with rank 0 is not supported.");
1755	    }
1756	
1757	    SmallVector<int64_t> globalShape(rank, cuda_tile::TensorViewType::kDynamic);
1758	    SmallVector<int64_t> globalStride(rank,
1759	                                      cuda_tile::TensorViewType::kDynamic);
1760	    // we can always assume the stride is 1
1761	    // because openai has assume this.
1762	    globalStride[rank - 1] = 1;
1763	
1764	    auto elemTy = ptrTy.getPointeeType();
1765	    unsigned elem_bytes = elemTy.getIntOrFloatBitWidth() / 8;
1766	    unsigned align_byte = kTMAAlignment / elem_bytes;
1767	
1768	    auto getConstInt = [&](Value stride) -> std::optional<int> {
1769	      if (auto constOp =
1770	              dyn_cast_or_null<arith::ConstantOp>(stride.getDefiningOp())) {
1771	        if (auto intAttr = dyn_cast<mlir::IntegerAttr>(constOp.getValue()))
1772	          return intAttr.getInt();
1773	      }
1774	      return std::nullopt;
1775	    };
1776	
1777	    SmallVector<Value> wrappedDynShapes;
1778	    // It is safe to assume that shapes are in the range [0, 2^32 - 1] which is
1779	    // the TMA hardware limit for shape. This ensures that if users explicitly
1780	    // want to use TMA for this operation, the shape parameters will satisfy TMA
1781	    // descriptor encoding requirements.
1782	    for (auto v : op.getShape())
1783	      wrappedDynShapes.push_back(
1784	          wrapIntoScalarTile(rewriter, v, /*attachAlignment=*/0, kMaxShape));
1785	    // Strides are required to be divisible by 16.
1786	    SmallVector<Value> wrappedDynStrides;
1787	    auto strides = op.getStrides();
1788	    for (size_t i = 0; i < rank; ++i) {
1789	      auto stride = strides[i];
1790	      auto constValOpt = getConstInt(stride);
1791	
1792	      if (i == rank - 1) {
1793	        // Last stride must be 1
1794	        if (!constValOpt.has_value() || constValOpt.value() != 1)
1795	          return rewriter.notifyMatchFailure(
1796	              loc, "the last stride is expected to be constexpr 1");
1797	      } else {
1798	        // Other strides should be divisible by 16-bytes
1799	        if (constValOpt.has_value() &&
1800	            (constValOpt.value() % align_byte != 0)) {
1801	          op.emitWarning("the stride is expected to be divisible by 16-bytes, "
1802	                         "may result in error");
1803	          // It is safe to assume that shapes are in the range [0, 2^40 - 1]
1804	          // which is the TMA hardware limit for stride. This ensures that if
1805	          // users explicitly want to use TMA for this operation, the stride
1806	          // parameters will satisfy TMA descriptor encoding requirements.
1807	          wrappedDynStrides.push_back(wrapIntoScalarTile(
1808	              rewriter, stride, /*attachAlignment=*/0, kMaxStride));
1809	        } else
1810	          wrappedDynStrides.push_back(wrapIntoScalarTile(
1811	              rewriter, stride, /*attachAlignment=*/align_byte, kMaxStride));
1812	      }
1813	    }
1814	
1815	    auto tensorViewTy =
1816	        cuda_tile::TensorViewType::get(ctx, elemTy, globalShape, globalStride);
1817	
1818	    auto tileIRPtrType = cuda_tile::PointerType::get(elemTy);
1819	    auto ptrTypeWrapper = cuda_tile::TileType::get(ctx, {}, tileIRPtrType);
1820	    auto ptrOp = UnrealizedConversionCastOp::create(
1821	                     rewriter, loc, ptrTypeWrapper, op.getBase())
1822	                     .getResult(0);
1823	    // Pointer is required to be divisible by 16.
1824	    auto ptrWithDivBy = cuda_tile::AssumeOp::create(
1825	                            rewriter, loc, ptrOp,
1826	                            cuda_tile::DivByAttr::get(
1827	                                ctx, kTMAAlignment, std::nullopt, std::nullopt))
1828	                            .getResult();
1829	
1830	    auto makeTensorViewOp = cuda_tile::MakeTensorViewOp::create(
1831	        rewriter, loc, tensorViewTy, ptrWithDivBy, wrappedDynShapes,
1832	        wrappedDynStrides);
1833	
1834	    SmallVector<int32_t> dimMap(rank);
1835	    std::iota(dimMap.begin(), dimMap.end(), 0);
1836	
1837	    auto descType = cast<triton::TensorDescType>(op.getResult().getType());
1838	    auto tileShape = descType.getShape();
1839	    SmallVector<int32_t> arrayOfi32Shape;
1840	    for (auto i64Shape : tileShape) {
1841	      arrayOfi32Shape.push_back(static_cast<int32_t>(i64Shape));
1842	    }
1843	
1844	        auto tilePartViewTy = cuda_tile::PartitionViewType::get(
1845	            ctx, rewriter.getDenseI32ArrayAttr(arrayOfi32Shape), tensorViewTy,
1846	            dimMap,
1847	            cuda_tile::PaddingValueAttr::get(ctx, cuda_tile::PaddingValue::zero));
1848	    
1849	        auto partViewOp = cuda_tile::MakePartitionViewOp::create(
1850	            rewriter, loc, tilePartViewTy, makeTensorViewOp);
1851	    
1852	        rewriter.replaceOp(op, partViewOp);
1853	    return success();
1854	  }
1855	};
