1891	class ConvertDotOp : public OpConversionPattern<triton::DotOp> {
1892	  using OpConversionPattern::OpConversionPattern;
1893	  LogicalResult
1894	  matchAndRewrite(triton::DotOp op, OpAdaptor adaptor,
1895	                  ConversionPatternRewriter &rewriter) const override {
1896	    auto converter = this->getTypeConverter();
1897	    SmallVector<Type> retTypes;
1898	    if (failed(converter->convertTypes(op->getResultTypes(), retTypes)))
1899	      return failure();
1900	
1901	    // Aux functions
1902	    auto isF32 = [](Value operand) {
1903	      return cast<RankedTensorType>(operand.getType()).getElementType().isF32();
1904	    };
1905	    auto zeroLike = [&](Value value) -> Value {
1906	      auto shapedType = cast<ShapedType>(value.getType());
1907	      Type elemType = shapedType.getElementType();
1908	
1909	      TypedAttr zeroAttr;
1910	      if (auto floatTy = dyn_cast<FloatType>(elemType)) {
1911	        zeroAttr = rewriter.getFloatAttr(floatTy, 0.0);
1912	      } else {
1913	        llvm_unreachable("unsupported element type for zeroLike");
1914	      }
1915	
1916	      auto c0Attr = DenseElementsAttr::get(shapedType, zeroAttr);
1917	      return cuda_tile::ConstantOp::create(
1918	          rewriter, op.getLoc(), value.getType(),
1919	          cast<DenseTypedElementsAttr>(c0Attr));
1920	    };
1921	    auto convertFloat = [&](Value value, FloatType dstFloatTy) -> Value {
1922	      auto srcTy = dyn_cast<cuda_tile::TileType>(value.getType());
1923	      auto dstTy = cuda_tile::TileType::get(srcTy.getShape(), dstFloatTy);
1924	      return cuda_tile::FToFOp::create(rewriter, op.getLoc(), dstTy, value);
1925	    };
1926	    auto sub = [&](Value a, Value b) -> Value {
1927	      return cuda_tile::SubFOp::create(
1928	          rewriter, op.getLoc(), a, b,
1929	          cuda_tile::RoundingModeAttr::get(
1930	              rewriter.getContext(), cuda_tile::RoundingMode::NEAREST_EVEN),
1931	          /*FlushToZeroModifier=*/nullptr);
1932	    };
1933	    auto add = [&](Value a, Value b) -> Value {
1934	      return cuda_tile::AddFOp::create(
1935	          rewriter, op.getLoc(), a, b,
1936	          cuda_tile::RoundingModeAttr::get(
1937	              rewriter.getContext(), cuda_tile::RoundingMode::NEAREST_EVEN),
1938	          /*FlushToZeroModifier=*/nullptr);
1939	    };
1940	    auto splitF32 = [&](Value input, unsigned N,
1941	                        FloatType dstFloatTy) -> llvm::SmallVector<Value, 3> {
1942	      llvm::SmallVector<Value, 3> splitInputs;
1943	
1944	      FloatType f32Ty = rewriter.getF32Type();
1945	      for (unsigned i = 0; i < N; ++i) {
1946	        Value dstValue = convertFloat(input, dstFloatTy);
1947	        if (i != N - 1) {
1948	          Value dstF32Value = convertFloat(dstValue, f32Ty);
1949	          input = sub(input, dstF32Value);
1950	        }
1951	        splitInputs.push_back(dstValue);
1952	      }
1953	      return splitInputs;
1954	    };
1955	    auto mma = [&](Value a, Value b, Value c) -> Value {
1956	      return cuda_tile::MmaFOp::create(rewriter, op->getLoc(), a, b, c);
1957	    };
1958	    auto replaceNansWithZeros = [&](Value value) -> Value {
1959	      // triton use arith::CmpFPredicate::UNO here, we use an ordered equal to
1960	      // replace it
1961	      auto nans = cuda_tile::CmpFOp::create(
1962	          rewriter, op.getLoc(), cuda_tile::ComparisonPredicate::EQUAL,
1963	          cuda_tile::ComparisonOrdering::ORDERED, value, value);
1964	      auto zero = zeroLike(value);
1965	      return cuda_tile::SelectOp::create(rewriter, op.getLoc(), nans, value,
1966	                                         zero);
1967	    };
1968	
1969	    // Non-IEEE mode, mixed precision
1970	    if (isF32(op.getA()) && isF32(op.getB()) &&
1971	        op.getInputPrecision() != InputPrecision::IEEE) {
1972	      FloatType computeTy;  // mma compute type
1973	      unsigned nSplits = 0; // number of splits for lhs and rhs
1974	      switch (op.getInputPrecision()) {
1975	      case InputPrecision::TF32: {
1976	        computeTy = rewriter.getTF32Type();
1977	        nSplits = 1;
1978	        break;
1979	      }
1980	      case InputPrecision::TF32x3: {
1981	        computeTy = rewriter.getTF32Type();
1982	        nSplits = 2;
1983	        break;
1984	      }
1985	      case InputPrecision::BF16x3: {
1986	        computeTy = rewriter.getBF16Type();
1987	        nSplits = 2;
1988	        break;
1989	      }
1990	      case InputPrecision::BF16x6: {
1991	        computeTy = rewriter.getBF16Type();
1992	        nSplits = 3;
1993	        break;
1994	      }
1995	      default:
1996	        return rewriter.notifyMatchFailure(op, "unsupported input precision");
1997	      }
1998	
1999	      const auto lhs_parts = splitF32(adaptor.getA(), nSplits, computeTy);
2000	      const auto rhs_parts = splitF32(adaptor.getB(), nSplits, computeTy);
2001	      const unsigned hi = 0, mid = 1, lo = 2;
2002	
2003	      if (nSplits == 1) {
2004	        // for TF32 mode, only one mma is needed
2005	        auto result = mma(lhs_parts[hi], rhs_parts[hi], adaptor.getC());
2006	        rewriter.replaceOp(op, result);
2007	        return success();
2008	      } else {
2009	        // for other mixed precision modes, multiple mmas are needed
2010	        auto result = zeroLike(adaptor.getC());
2011	        if (nSplits > 2) {
2012	          result = mma(lhs_parts[mid], rhs_parts[mid], result);
2013	          result = mma(lhs_parts[lo], rhs_parts[hi], result);
2014	          result = mma(lhs_parts[hi], rhs_parts[lo], result);
2015	        }
2016	        if (nSplits > 1) {
2017	          result = mma(lhs_parts[mid], rhs_parts[hi], result);
2018	          result = mma(lhs_parts[hi], rhs_parts[mid], result);
2019	          result = replaceNansWithZeros(result);
2020	        }
2021	        result = mma(lhs_parts[hi], rhs_parts[hi], result);
2022	        result = add(result, adaptor.getC());
2023	        rewriter.replaceOp(op, result);
2024	        return success();
2025	      }
2026	    }
2027	
2028	    // IEEE mode, directly lower to mma
2029	    auto opElType =
2030	        cast<cuda_tile::TileType>(adaptor.getA().getType()).getElementType();
2031	    if (opElType.isInteger(8)) {
2032	      // To lower IMMA, we must distinguish between signed and unsigned at the
2033	      // operation level. Triton IR is signless, and there are no attributes for
2034	      // us to recover this information. Hence, here, for integer type, we
2035	      // default to signed.
2036	      rewriter.replaceOpWithNewOp<cuda_tile::MmaIOp>(
2037	          op, adaptor.getA(), adaptor.getB(), adaptor.getC(),
2038	          cuda_tile::Signedness::Signed, cuda_tile::Signedness::Signed);
2039	    } else if (opElType.isFloat()) {
2040	      rewriter.replaceOpWithNewOp<cuda_tile::MmaFOp>(
2041	          op, adaptor.getA(), adaptor.getB(), adaptor.getC());
2042	    } else {

