22	enum class IdentityValue {
23	  NONE,
24	  ZERO,
25	  ONE,
26	  POS_INF,
27	  NEG_INF,
28	  MAX_SIGNED,
29	  MIN_SIGNED,
30	  MAX_UNSIGNED,
31	  MIN_UNSIGNED
32	};
