34	// Helper function to convert IdentityValue to string for debugging
35	static const char *identityValueToString(IdentityValue value) {
36	  switch (value) {
37	  case IdentityValue::NONE:
38	    return "NONE";
39	  case IdentityValue::ZERO:
40	    return "ZERO";
41	  case IdentityValue::ONE:
42	    return "ONE";
43	  case IdentityValue::POS_INF:
44	    return "POS_INF";
45	  case IdentityValue::NEG_INF:
46	    return "NEG_INF";
47	  case IdentityValue::MAX_SIGNED:
48	    return "MAX_SIGNED";
49	  case IdentityValue::MIN_SIGNED:
50	    return "MIN_SIGNED";
51	  case IdentityValue::MAX_UNSIGNED:
52	    return "MAX_UNSIGNED";
53	  case IdentityValue::MIN_UNSIGNED:
54	    return "MIN_UNSIGNED";
55	  }
56	  return "UNKNOWN";
57	}
