59	Attribute getIdentitiesAttr(MLIRContext *context,
60	                            ConversionPatternRewriter &rewriter, Type eltType,
61	                            IdentityValue value) {
62	  if (auto floatTy = dyn_cast<FloatType>(eltType)) {
63	    const auto &semantics = floatTy.getFloatSemantics();
64	    switch (value) {
65	    case IdentityValue::ZERO:
66	      return FloatAttr::get(floatTy, APFloat::getZero(semantics));
67	    case IdentityValue::ONE:
68	      return FloatAttr::get(floatTy, APFloat::getOne(semantics));
69	    case IdentityValue::NEG_INF:
70	      return FloatAttr::get(floatTy,
71	                            APFloat::getInf(semantics, /*negative=*/true));
72	    case IdentityValue::POS_INF:
73	      return FloatAttr::get(floatTy,
74	                            APFloat::getInf(semantics, /*negative=*/false));
75	    default:
76	      llvm_unreachable("unexpected identity value for float type");
77	    }
78	  }
79	
80	  if (auto intTy = dyn_cast<IntegerType>(eltType)) {
81	    auto width = intTy.getWidth();
82	    switch (value) {
83	    case IdentityValue::ZERO:
84	      return IntegerAttr::get(intTy, APInt::getZero(width));
85	    case IdentityValue::ONE:
86	      return IntegerAttr::get(intTy, APInt(width, 1));
87	    case IdentityValue::MAX_SIGNED:
88	      return IntegerAttr::get(intTy, APInt::getSignedMaxValue(width));
89	    case IdentityValue::MIN_SIGNED:
90	      return IntegerAttr::get(intTy, APInt::getSignedMinValue(width));
91	    case IdentityValue::MAX_UNSIGNED:
92	      return IntegerAttr::get(intTy, APInt::getMaxValue(width));
93	    case IdentityValue::MIN_UNSIGNED:
94	      return IntegerAttr::get(intTy, APInt::getMinValue(width));
95	    default:
96	      llvm_unreachable("unexpected identity value for integer type");
97	    }
98	  }
99	
100	  assert(false && "unexpected data type for reduceOp.");
101	}
