103	bool isI8OrI1ElementTensor(Type type) {
104	  auto tensorTy = dyn_cast<cuda_tile::TileType>(type);
105	  if (!tensorTy)
106	    return false;
107	  auto elmTy = tensorTy.getElementType();
108	  if (auto intTy = dyn_cast<IntegerType>(elmTy)) {
109	    auto bitWidth = intTy.getIntOrFloatBitWidth();
110	    return bitWidth == 8 || bitWidth == 1;
111	  }
112	  return false;
113	}
