117	// Helper function to find operations that consume both block arguments
118	static SmallVector<Operation *> findConsumingOperations(Value inputOperand,
119	                                                        Value identityOperand) {
120	  SmallVector<Operation *> consumingOps;
121	
122	  // Collect all operations that use the input operand
123	  SmallPtrSet<Operation *, 8> inputUsers;
124	  for (auto &use : inputOperand.getUses()) {
125	    inputUsers.insert(use.getOwner());
126	  }
127	
128	  // Check which of these also use the identity operand
129	  for (auto &use : identityOperand.getUses()) {
130	    Operation *op = use.getOwner();
131	    if (inputUsers.contains(op)) {
132	      // Verify the operation actually uses both values as operands
133	      bool usesInput = llvm::any_of(op->getOperands(), [&](Value operand) {
134	        return operand == inputOperand;
135	      });
136	      bool usesIdentity = llvm::any_of(op->getOperands(), [&](Value operand) {
137	        return operand == identityOperand;
138	      });
139	
140	      if (usesInput && usesIdentity) {
141	        consumingOps.push_back(op);
142	      }
143	    }
144	  }
145	
146	  return consumingOps;
147	}
148	
149	// Helper function to analyze operations and get consistent identity
150	static FailureOr<IdentityValue>
151	analyzeConsistentIdentity(ArrayRef<Operation *> consumingOps,
152	                          size_t pairIndex) {
153	  if (consumingOps.empty()) {
154	    LLVM_DEBUG(llvm::dbgs()
155	               << "Warning: No consumer found for Arguments in pair "
156	               << pairIndex << ".\n");
157	    return IdentityValue::NONE;
158	  }
159	
160	  // Helper to analyze operation and determine reduction type
161	  auto analyzeOp = [&](Operation *op) -> IdentityValue {
162	    // Integer comparison operations
163	    if (auto cmp = dyn_cast<arith::CmpIOp>(op)) {
164	      switch (cmp.getPredicate()) {
165	      case arith::CmpIPredicate::sgt:
166	        return IdentityValue::MIN_SIGNED;
167	      case arith::CmpIPredicate::slt:
168	        return IdentityValue::MAX_SIGNED;
169	      case arith::CmpIPredicate::ugt:
170	        return IdentityValue::MIN_UNSIGNED;
171	      case arith::CmpIPredicate::ult:
172	        return IdentityValue::MAX_UNSIGNED;
173	      default:
174	        break;
175	      }
176	    }
177	
178	    // Float comparison operations
179	    if (auto cmp = dyn_cast<arith::CmpFOp>(op)) {
180	      switch (cmp.getPredicate()) {
181	      case arith::CmpFPredicate::OGT:
182	        return IdentityValue::NEG_INF;
183	      case arith::CmpFPredicate::OLT:
184	        return IdentityValue::POS_INF;
185	      default:
186	        break;
187	      }
188	    }
189	
190	    // Arithmetic operations
191	    if (isa<arith::AddFOp, arith::AddIOp>(op))
192	      return IdentityValue::ZERO;
193	    if (isa<arith::MulFOp, arith::MulIOp>(op))
194	      return IdentityValue::ONE;
195	    if (isa<arith::XOrIOp>(op))
196	      return IdentityValue::ZERO;
197	    if (isa<arith::AndIOp>(op))
198	      // Bitwise AND identity requires all bits set to 1, not just value 1
199	      return IdentityValue::MAX_UNSIGNED;
200	    if (isa<arith::OrIOp>(op))
201	      return IdentityValue::ZERO;
202	
203	    // Min/Max operations
204	    if (isa<arith::MinNumFOp, arith::MinimumFOp>(op))
205	      return IdentityValue::POS_INF;
206	    if (isa<arith::MaxNumFOp, arith::MaximumFOp>(op))
207	      return IdentityValue::NEG_INF;
208	    if (isa<arith::MinSIOp>(op))
209	      return IdentityValue::MAX_SIGNED;
210	    if (isa<arith::MinUIOp>(op))
211	      return IdentityValue::MAX_UNSIGNED;
212	    if (isa<arith::MaxSIOp>(op))
213	      return IdentityValue::MIN_SIGNED;
214	    if (isa<arith::MaxUIOp>(op))
215	      return IdentityValue::MIN_UNSIGNED;
216	
217	    assert(!isa<triton::CallOp>(op) && "CallOp need to be inlined");
218	    return IdentityValue::NONE;
219	  };
220	
221	  // Analyze all consuming operations to get their identities
222	  SmallVector<IdentityValue> identityValues;
223	  for (Operation *op : consumingOps) {
224	    IdentityValue identity = analyzeOp(op);
225	    if (identity != IdentityValue::NONE) {
226	      identityValues.push_back(identity);
227	    }
228	  }
229	
230	  if (identityValues.empty()) {
231	    LLVM_DEBUG(
232	        llvm::dbgs()
233	        << "Warning: No valid identity values found for Arguments in pair "
234	        << pairIndex << ".\n");
235	    return IdentityValue::NONE;
236	  }
237	
238	  // Check if all identities are the same (with early exit optimization)
239	  IdentityValue firstIdentity = identityValues[0];
240	  for (size_t j = 1; j < identityValues.size(); ++j) {
241	    if (identityValues[j] != firstIdentity) {
242	      llvm::errs() << "Error: Arguments pair in combineOp are consumed by "
243	                      "operations with different identities: "
244	                   << "first=" << identityValueToString(firstIdentity)
245	                   << ", found=" << identityValueToString(identityValues[j])
246	                   << ", please check if combineOp satisfies associative and "
247	                      "commutative laws.\n";
248	      return failure();
249	    }
250	  }
251	
252	  return firstIdentity;
253	}
