255	FailureOr<ArrayAttr>
256	getIdentitiesFromCombineOp(Region &combineOp, ArrayRef<Type> retType,
257	                           ConversionPatternRewriter &rewriter) {
258	  SmallVector<Attribute> attributes;
259	  MLIRContext *context = combineOp.getContext();
260	  // Here, it tries to deduce the correct identity, but even if it fails,
261	  // the backend can still calculate the correct result.
262	  // It's hard to code a general logic to cover all complicate region
263	  // calculations. Hence, backend should ensure ReduceOp to be identity
264	  // insensitive in power of 2 cases. Details refer to:
265	  Block &block = combineOp.front();
266	  auto blockArgs = block.getArguments();
267	  size_t numReturns = blockArgs.size() / 2;
268	
269	#ifndef NDEBUG
270	  // Validate that we have an even number of arguments
271	  assert(blockArgs.size() % 2 == 0 &&
272	         "Combine operation must have an even number of block arguments");
273	  // Number of returns should be half of all operands
274	  assert(retType.size() == numReturns &&
275	         "Number of return types must be half of block arguments");
276	  // Validate the block arguments types with the retType
277	  // First half of blockArgs are input operands, second half are identities
278	  for (size_t i = 0; i < numReturns; i++) {
279	    // Check input operand type
280	    assert(blockArgs[i].getType() ==
281	               dyn_cast<ShapedType>(retType[i]).getElementType() &&
282	           "block argument type mismatch for input operand");
283	    // Check identity type
284	    assert(blockArgs[i + numReturns].getType() ==
285	               dyn_cast<ShapedType>(retType[i]).getElementType() &&
286	           "block argument type mismatch for identity");
287	  }
288	#endif // NDEBUG
289	
290	  // Process each pair of arguments
291	  for (size_t i = 0; i < numReturns; i++) {
292	    Value inputOperand = blockArgs[i];
293	    Value identityOperand = blockArgs[i + numReturns];
294	    IdentityValue identityValue = IdentityValue::ZERO;
295	
296	    // Find operations and analyze their identities
297	    SmallVector<Operation *> consumingOps =
298	        findConsumingOperations(inputOperand, identityOperand);
299	    FailureOr<IdentityValue> identityValueOr =
300	        analyzeConsistentIdentity(consumingOps, i);
301	
302	    if (failed(identityValueOr)) {
303	      // Identity consistency error - propagate failure
304	      return failure();
305	    }
306	
307	    IdentityValue result = *identityValueOr;
308	    if (result == IdentityValue::NONE) {
309	      // Use dummy identity for cases with no valid identity value
310	      LLVM_DEBUG(llvm::dbgs()
311	                 << "Using dummy identity (ZERO) for pair " << i << ".\n");
312	      identityValue = IdentityValue::ZERO;
313	    } else {
314	      identityValue = result;
315	    }
316	    attributes.push_back(getIdentitiesAttr(
317	        context, rewriter, dyn_cast<ShapedType>(retType[i]).getElementType(),
318	        identityValue));
319	  }
320	
321	  return ArrayAttr::get(context, attributes);
322	}
