324	bool canMapToCudaTile(triton::FuncOp op, CudaTileTypeConverter &typeConverter) {
325	  // kernel in cuda tile do not return any result.
326	  if (op.getNumResults() > 0 && op.getSymVisibility() == "public")
327	    return false;
328	  // The operation is legal if we cannot convert a type to cuda tile.
329	  SmallVector<Type> newTypes;
330	  if (failed(typeConverter.convertTypes(op.getFunctionType().getInputs(),
331	                                        newTypes)))
332	    return false;
333	  if (failed(typeConverter.convertTypes(op.getFunctionType().getResults(),
334	                                        newTypes)))
335	    return false;
336	  return true;
337	}
