339	/// Upcast input (expected to be a cuda tile tensor) to i16 from i1 or i8,
340	/// otherwise just return the input.
341	Value upCastOrSelf(OpBuilder &builder, Location loc, Value input,
342	                   Signedness signedness, IntegerUpCast integerUpCast) {
343	  auto type = dyn_cast<cuda_tile::TileType>(input.getType());
344	  // Cast not needed.
345	  if (integerUpCast == IntegerUpCast::None || !isI8OrI1ElementTensor(type))
346	    return input;
347	  assert(integerUpCast == IntegerUpCast::To_I16 &&
348	         "only upcast to i16 is supported");
349	  auto tensorTy =
350	      cuda_tile::TileType::get(type.getShape(), builder.getIntegerType(16));
351	  auto signednessAttr = signedness == Signedness::Unsigned
352	                            ? cuda_tile::Signedness::Unsigned
353	                            : cuda_tile::Signedness::Signed;
354	  return cuda_tile::ExtIOp::create(builder, loc, tensorTy, input,
355	                                   signednessAttr);
356	}
357	
358	/// Downcast the result of `createOp` back to i1 or i8.
359	Value downCastOrSelf(
360	    OpBuilder &builder, Location loc, ArrayRef<Value> operands, Type retType,
361	    llvm::function_ref<Value(OpBuilder &, Location, Type, ArrayRef<Value>)>
362	        createOp,
363	    IntegerUpCast integerUpCast) {
364	  if (integerUpCast == IntegerUpCast::None || !isI8OrI1ElementTensor(retType))
365	    return createOp(builder, loc, retType, operands);
366	
367	  auto tensorTy =
368	      cuda_tile::TileType::get(cast<cuda_tile::TileType>(retType).getShape(),
369	                               builder.getIntegerType(16));
370	  auto newOp = createOp(builder, loc, tensorTy, operands);
371	  return cuda_tile::TruncIOp::create(builder, loc, retType, newOp);
372	}
373	
374	LogicalResult matchAndRewriteGenericOpImpl(
375	    Operation *op, ValueRange operands, const TypeConverter *converter,
376	    ConversionPatternRewriter &rewriter,
377	    llvm::function_ref<Value(OpBuilder &, Location, Type, ArrayRef<Value>)>
378	        createOp,
379	    Signedness signedness, IntegerUpCast integerUpCast) {
380	  if (!op->hasTrait<OpTrait::OneResult>())
381	    return rewriter.notifyMatchFailure(op, "expect single result operation");
382	
383	  auto loc = op->getLoc();
384	  SmallVector<Value> newOperands;
385	  for (auto input : operands)
386	    newOperands.push_back(
387	        upCastOrSelf(rewriter, loc, input, signedness, integerUpCast));
388	
389	  Type retType = converter->convertType(op->getResult(0).getType());
390	  auto newOp = downCastOrSelf(rewriter, loc, newOperands, retType, createOp,
391	                              integerUpCast);
392	  rewriter.replaceOp(op, newOp);
393	  return success();
394	}
