396	CudaTileTypeConverter::CudaTileTypeConverter() {
397	  // in python api level, we use 0 as a placeholder for tensordesc type
398	  // so we need to convert it to i32 type
399	  addConversion([](triton::TensorDescType type) {
400	    MLIRContext *ctx = type.getContext();
401	    auto descBlock = type.getBlockType();
402	    auto tileShape = descBlock.getShape();
403	    auto rank = tileShape.size();
404	
405	    SmallVector<int64_t> globalShape(rank, cuda_tile::TensorViewType::kDynamic);
406	    SmallVector<int64_t> globalStride(rank,
407	                                      cuda_tile::TensorViewType::kDynamic);
408	    globalStride[rank - 1] = 1;
409	
410	    auto pointeeType = descBlock.getElementType();
411	    if (auto intTy = dyn_cast<mlir::IntegerType>(pointeeType)) {
412	      pointeeType = mlir::IntegerType::get(ctx, intTy.getWidth(),
413	                                           mlir::IntegerType::Signless);
414	    }
415	
416	    auto tensorViewTy = cuda_tile::TensorViewType::get(
417	        ctx, pointeeType, globalShape, globalStride);
418	
419	    SmallVector<int32_t> dimMap(rank);
420	    std::iota(dimMap.begin(), dimMap.end(), 0);
421	
422	    SmallVector<int32_t> arrayOfi32Shape;
423	    for (auto i64Shape : tileShape) {
424	      arrayOfi32Shape.push_back(i64Shape);
425	    }
426	    auto shapeAttr = DenseI32ArrayAttr::get(ctx, arrayOfi32Shape);
427	
428	        return cuda_tile::PartitionViewType::get(
429	            ctx, shapeAttr, tensorViewTy, dimMap,
430	            cuda_tile::PaddingValueAttr::get(ctx, cuda_tile::PaddingValue::zero));
431	  });
432	  addConversion([](cuda_tile::TensorViewType type) { return type; });
433	  addConversion([](cuda_tile::PartitionViewType type) { return type; });
434	  addConversion([](cuda_tile::TokenType type) { return type; });
435	  addConversion(
436	      [](FloatType type) { return cuda_tile::TileType::get({}, type); });
437	  addConversion(
438	      [](IntegerType type) { return cuda_tile::TileType::get({}, type); });
439	  // Convert a pointer type into a zero-ranked tensor type, where the element
440	  // type is a CUDA pointer type.
441	  addConversion([this](triton::PointerType ptrType) -> Type {
442	    auto pointeeType = ptrType.getPointeeType();
443	    // Do not crash on cuda tile verifier if we get a ptr<tensor>.
444	    if (isa<RankedTensorType>(pointeeType))
445	      return Type();
446	    return cuda_tile::TileType::get({},
447	                                    cuda_tile::PointerType::get(pointeeType));
448	  });
449	  // Convert a ranked tensor type to a CUDA tensor type. There are two
450	  // possible conversions: 1.	When the element type is a pointer type: Extract
451	  // the pointer type element from the zero-ranked tensor type produced by the
452	  // type converter, then repack it into a new tensor while adjusting the
453	  // shape accordingly.
454	  // 2. When the element type is an integer or a floating point scalar type,
455	  // pack it into a CUDA tensor type adjusting the shape accordingly.
456	  addConversion([this](RankedTensorType tensorType) {
457	    auto elemType = tensorType.getElementType();
458	    if (isa<triton::PointerType>(elemType)) {
459	      cuda_tile::TileType tensorTy =
460	          cast<cuda_tile::TileType>(convertType(elemType));
461	      return cuda_tile::TileType::get(tensorType.getShape(),
462	                                      tensorTy.getElementType());
463	    }
464	    return cuda_tile::TileType::get(tensorType.getShape(), elemType);
465	  });
466	}
