2204	// Clamp operation clamps a value x between min and max bounds:
2205	// clamp(x, min, max) = min(max(x, min), max)
2206	//
2207	// Examples:
2208	// For x = -3 with bounds [0,2]:
2209	//   max(-3, 0) = 0   // First clamp to lower bound
2210	//   min(0, 2) = 0    // Then clamp to upper bound
2211	//
2212	// For x = 5 with bounds [0,2]:
2213	//   max(5, 0) = 5    // First clamp to lower bound
2214	//   min(5, 2) = 2    // Then clamp to upper bound
2215	//
2216	// The operation can either propagate NaN values (ALL) or not (NONE)
2217	class ConvertClampFOp : public OpConversionPattern<triton::ClampFOp> {
2218	  using OpConversionPattern::OpConversionPattern;
2219	
2220	  LogicalResult
2221	  matchAndRewrite(triton::ClampFOp op, OpAdaptor adaptor,
2222	                  ConversionPatternRewriter &rewriter) const override {
2223	    auto loc = op.getLoc();
2224	
2225	    auto converter = getTypeConverter();
2226	    Type xTy = converter->convertType(op.getX().getType());
2227	    if (!xTy)
2228	      return rewriter.notifyMatchFailure(
2229	          op, "failed to convert operand types of clampf");
2230	
2231	    auto nanModifier = op.getPropagateNan() == PropagateNan::ALL
2232	                           ? rewriter.getUnitAttr()
2233	                           : nullptr;
2234	
2235	    auto v = cuda_tile::MaxFOp::create(rewriter, loc, xTy, adaptor.getX(),
2236	                                       adaptor.getMin(), nanModifier,
2237	                                       /*flush_to_zero_modifier=*/nullptr);
2238	    rewriter.replaceOpWithNewOp<cuda_tile::MinFOp>(
2239	        op, v, adaptor.getMax(), nanModifier,
2240	        /*flush_to_zero_modifier=*/nullptr);
2241	    return success();
2242	  }
2243	};
