2245	class ConvertSplitOp : public OpConversionPattern<triton::SplitOp> {
2246	  using OpConversionPattern::OpConversionPattern;
2247	
2248	  LogicalResult
2249	  matchAndRewrite(triton::SplitOp op, OpAdaptor adaptor,
2250	                  ConversionPatternRewriter &rewriter) const override {
2251	    // Convert result types.
2252	    assert(op.getResult(0).getType() == op.getResult(1).getType() &&
2253	           "result type mismatch");
2254	    Type resultType =
2255	        getTypeConverter()->convertType(op.getResult(0).getType());
2256	    if (!resultType)
2257	      return rewriter.notifyMatchFailure(op, "failed to convert result type");
2258	
2259	    // Split the last dimension with two cuda_tile.extract.
2260	    auto loc = op.getLoc();
2261	    Value src = adaptor.getSrc();
2262	    cuda_tile::TileType srcType = cast<cuda_tile::TileType>(src.getType());
2263	    cuda_tile::TileType constType =
2264	        cuda_tile::TileType::get({}, rewriter.getI32Type());
2265	    auto c0Attr = DenseIntElementsAttr::get(constType, {0});
2266	    Value c0 = cuda_tile::ConstantOp::create(rewriter, loc, constType, c0Attr);
2267	    auto c1Attr = DenseIntElementsAttr::get(constType, {1});
2268	    Value c1 = cuda_tile::ConstantOp::create(rewriter, loc, constType, c1Attr);
2269	    SmallVector<Value> indices0(srcType.getRank() - 1, c0);
2270	    SmallVector<Value> indices1(srcType.getRank() - 1, c0);
2271	    indices0.push_back(c0);
2272	    indices1.push_back(c1);
2273	    SmallVector<int64_t> extractedShape =
2274	        llvm::to_vector(llvm::drop_end(srcType.getShape()));
2275	    extractedShape.push_back(1);
2276	    auto extractedType =
2277	        cuda_tile::TileType::get(extractedShape, srcType.getElementType());
2278	    Value extract0 = cuda_tile::ExtractOp::create(rewriter, loc, extractedType,
2279	                                                  src, indices0);
2280	    Value extract1 = cuda_tile::ExtractOp::create(rewriter, loc, extractedType,
2281	                                                  src, indices1);
2282	
2283	    // Drop the last dimension.
2284	    SmallVector<Value> repls;
2285	    repls.push_back(
2286	        cuda_tile::ReshapeOp::create(rewriter, loc, resultType, extract0));
2287	    repls.push_back(
2288	        cuda_tile::ReshapeOp::create(rewriter, loc, resultType, extract1));
2289	    rewriter.replaceOp(op, repls);
2290	    return success();
2291	  }
2292	};
