2449	/// Convert the given tt.constancy attribute.
2450	static Value convertConstAttr(OpBuilder &b, Value v, Location loc,
2451	                              const AxisInfo &info) {
2452	  auto type = cast<cuda_tile::TileType>(v.getType());
2453	  if (type.getRank() == 0)
2454	    return v;
2455	  assert(type.getRank() == info.getRank() && "rank mismatch");
2456	  auto pred = cuda_tile::SameElementsAttr::get(
2457	      b.getContext(), b.getDenseI64ArrayAttr(info.getConstancy()));
2458	  return cuda_tile::AssumeOp::create(b, loc, v, pred);
2459	}
