2461	/// Insert a cuda_tile.assume op based on the divisibility / contiguity of the
2462	/// given Triton axis attributes.
2463	static Value convertDivByAndContAttr(OpBuilder &b, Value v, Location loc,
2464	                                     const AxisInfo &info) {
2465	  auto type = cast<cuda_tile::TileType>(v.getType());
2466	
2467	  // Find the dimension with the largest divisibility.
2468	  int64_t divisor = 1;
2469	  std::optional<int64_t> every = std::nullopt;
2470	  std::optional<int64_t> along = std::nullopt;
2471	  for (int64_t i = 0, e = info.getRank(); i < e; ++i) {
2472	    if (info.getDivisibility(i) > divisor ||
2473	        (info.getDivisibility(i) == divisor &&
2474	         info.getContiguity(i) > every.value_or(1))) {
2475	      divisor = info.getDivisibility(i);
2476	      every = info.getContiguity(i);
2477	      along = i;
2478	    }
2479	  }
2480	
2481	  if (type.getRank() == 0) {
2482	    // Rank 0 (scalar): drop contiguity.
2483	    every = std::nullopt;
2484	    along = std::nullopt;
2485	  }
2486	
2487	  cuda_tile::DivByAttr pred =
2488	      cuda_tile::DivByAttr::get(b.getContext(), divisor, every, along);
2489	  return cuda_tile::AssumeOp::create(b, loc, v, pred);
2490	}
