2492	/// Helper struct that stores the Triton axis information for a given SSA
2493	/// value, which was injected by the user. The AxisInfo object stores not only
2494	/// the injected information. That's because divisibility and contiguity in
2495	/// Triton can be set independently, whereas they always come as a pair in
2496	/// cuda_tile. (And must be set together in cuda_tile.)
2497	struct Assumption {
2498	  Assumption(Value value, const AxisInfo &info, bool hasDivByAttr,
2499	             bool hasContAttr, bool hasConstrAttr)
2500	      : value(value), info(info), hasDivByAttr(hasDivByAttr),
2501	        hasContAttr(hasContAttr), hasConstAttr(hasConstrAttr) {}
2502	  Value value;
2503	  AxisInfo info;
2504	  bool hasDivByAttr;
2505	  bool hasContAttr;
2506	  bool hasConstAttr;
2507	};
