2509	/// Create a cuda_tile.assume op for the given assumption.
2510	static void assumeAxisAttributes(RewriterBase &rewriter,
2511	                                 TypeConverter &converter,
2512	                                 const Assumption &assumption) {
2513	  assert((assumption.hasDivByAttr || assumption.hasContAttr ||
2514	          assumption.hasConstAttr) &&
2515	         "no attributes found to forward");
2516	  OpBuilder::InsertionGuard g(rewriter);
2517	  Value v = assumption.value;
2518	  Location loc = v.getLoc();
2519	  if (auto bbArg = dyn_cast<BlockArgument>(v)) {
2520	    rewriter.setInsertionPointToStart(bbArg.getOwner());
2521	  } else {
2522	    rewriter.setInsertionPointAfter(v.getDefiningOp());
2523	  }
2524	
2525	  // Insert an unrealized_conversion_cast to the respective cuda_tile type.
2526	  Type convertedType = converter.convertType(v.getType());
2527	  assert(convertedType && "could not convert type");
2528	  auto tileType = dyn_cast<cuda_tile::TileType>(convertedType);
2529	  assert(tileType && "axis attribute not supported on non-tensor type");
2530	  if (!isa<IntegerType, cuda_tile::PointerType>(tileType.getElementType()))
2531	    return;
2532	  Value val =
2533	      UnrealizedConversionCastOp::create(rewriter, loc, convertedType, v)
2534	          .getResult(0);
2535	  Operation *firstCast = val.getDefiningOp();
2536	
2537	  // Create cuda_tile.assume op.
2538	  if (assumption.hasConstAttr)
2539	    val = convertConstAttr(rewriter, val, loc, assumption.info);
2540	  if (assumption.hasDivByAttr || assumption.hasContAttr)
2541	    val = convertDivByAndContAttr(rewriter, val, loc, assumption.info);
2542	
2543	  // Insert an unrealized_conversion_cast back to the original type.
2544	  val = UnrealizedConversionCastOp::create(rewriter, loc, v.getType(), val)
2545	            .getResult(0);
2546	  rewriter.replaceAllUsesExcept(v, val, firstCast);
2547	}
