2563	static void
2564	checkDivisibilityForDescriptorOps(mlir::ModuleOp op,
2565	                                  ModuleAxisInfoAnalysis &axisInfo) {
2566	  auto checkDivisibility = [&](Operation *op, mlir::ValueRange indices,
2567	                               Value desc) -> void {
2568	    auto tensorDescType = dyn_cast<triton::TensorDescType>(desc.getType());
2569	    if (!tensorDescType)
2570	      return;
2571	    auto tileSizes = tensorDescType.getBlockType().getShape();
2572	    for (size_t i = 0; i < indices.size(); i++) {
2573	      auto *info = axisInfo.getAxisInfo(indices[i]);
2574	      if (!info) {
2575	        op->emitWarning()
2576	            << "divisibility info not found for offset in dimension " << i
2577	            << " (offset: " << indices[i] << "), "
2578	            << "but tile size requires divisibility by " << tileSizes[i]
2579	            << " in tileir 13.1. Please add tl.assume(offset % block_shape == "
2580	               "0) if the offset is always divisible by the block shape.";
2581	      }
2582	      auto divisibility = info->getDivisibility(0);
2583	      if (divisibility % tileSizes[i] != 0) {
2584	        op->emitWarning()
2585	            << "divisibility at dimension " << i << ": offset divisibility is "
2586	            << divisibility << " but tile size requires divisibility by "
2587	            << tileSizes[i]
2588	            << " in tileir 13.1. Please add tl.assume(offset % block_shape == "
2589	               "0) if the offset is always divisible by the block shape.";
2590	      }
2591	    }
2592	  };
2593	
2594	  op->walk([&](Operation *op) {
2595	    if (auto descriptorStoreOp = dyn_cast<triton::DescriptorStoreOp>(op)) {
2596	      checkDivisibility(op, descriptorStoreOp.getIndices(),
2597	                        descriptorStoreOp.getDesc());
2598	    } else if (auto descriptorLoadOp = dyn_cast<triton::DescriptorLoadOp>(op)) {
2599	      checkDivisibility(op, descriptorLoadOp.getIndices(),
2600	                        descriptorLoadOp.getDesc());
2601	    }
2602	  });
2603	}
