2605	static void convertTmaDescriptorOps(Operation *op, TypeConverter &converter) {
2606	  IRRewriter rewriter(op->getContext());
2607	  auto ctx = op->getContext();
2608	  auto loc = op->getLoc();
2609	  op->walk([&](Operation *op) {
2610	    if (auto funcOp = dyn_cast<triton::FuncOp>(op)) {
2611	      for (size_t i = 0; i < funcOp.getNumArguments(); i++) {
2612	        Value tensorDesc = funcOp.getArgument(i);
2613	        if (isa<triton::TensorDescType>(tensorDesc.getType())) {
2614	          // [tensordesc, ptr, shape, stride]
2615	          // 'i' is the tensordesc type
2616	          int argIdx = i;
2617	          rewriter.setInsertionPointToStart(&funcOp.getBody().front());
2618	          auto tensorDescType =
2619	              cast<triton::TensorDescType>(tensorDesc.getType());
2620	          auto descBlock = tensorDescType.getBlockType();
2621	          auto rank = descBlock.getRank();
2622	          if (rank == 0) {
2623	            op->emitError("Host TMA descriptor with rank 0 is not supported.");
2624	            return WalkResult::interrupt();
2625	          }
2626	
2627	          auto pointeeType = descBlock.getElementType();
2628	          if (auto intTy = dyn_cast<mlir::IntegerType>(pointeeType)) {
2629	            pointeeType = mlir::IntegerType::get(ctx, intTy.getWidth(),
2630	                                                 mlir::IntegerType::Signless);
2631	          }
2632	          unsigned elem_bytes = pointeeType.getIntOrFloatBitWidth() / 8;
2633	          unsigned align_byte = kTMAAlignment / elem_bytes;
2634	
2635	          // 'i + 1' is the pointer of the global tensor
2636	          auto ptrArg = funcOp.getArgument(i + 1);
2637	          i = i + 1;
2638	          SmallVector<Value> shape;
2639	          for (size_t j = 0; j < rank; j++)
2640	            shape.push_back(funcOp.getArgument(i + j + 1));
2641	          i = i + rank;
2642	          SmallVector<Value> stride;
2643	          for (size_t j = 0; j < rank; j++)
2644	            stride.push_back(funcOp.getArgument(i + j + 1));
2645	          i = i + rank - 1;
2646	
2647	          SmallVector<Value> wrappedDynShapes;
2648	          // It is safe to assume that shapes are in the range [0, 2^32 - 1]
2649	          // which is the TMA hardware limit for shape. This ensures that if
2650	          // users explicitly want to use TMA for this operation, the shape
2651	          // parameters will satisfy TMA descriptor encoding requirements.
2652	          for (auto v : shape)
2653	            wrappedDynShapes.push_back(wrapIntoScalarTile(
2654	                rewriter, v, /*attachAlignment=*/0, kMaxShape));
2655	
2656	          SmallVector<Value> wrappedDynStrides;
2657	          // It is safe to assume that strides are in the range [0, 2^40 - 1]
2658	          // which is the TMA hardware limit for stride. This ensures that if
2659	          // users explicitly want to use TMA for this operation, the stride
2660	          // parameters will satisfy TMA descriptor encoding requirements.
2661	          for (int i = 0; i < stride.size() - 1; i++)
2662	            wrappedDynStrides.push_back(
2663	                wrapIntoScalarTile(rewriter, stride[i],
2664	                                   /*attachAlignment=*/align_byte, kMaxStride));
2665	
2666	          auto tileIRPtrType = cuda_tile::PointerType::get(pointeeType);
2667	          auto ptrTypeWrapper =
2668	              cuda_tile::TileType::get(ctx, {}, tileIRPtrType);
2669	          auto ptrOp = UnrealizedConversionCastOp::create(
2670	                           rewriter, loc, ptrTypeWrapper, ptrArg)
2671	                           .getResult(0);
2672	
2673	          // we can always assume the pointer is divisible by 16
2674	          // because openai has already make it into host tma api.
2675	          auto ptrWithDivBy =
2676	              cuda_tile::AssumeOp::create(
2677	                  rewriter, loc, ptrOp,
2678	                  cuda_tile::DivByAttr::get(ctx, kTMAAlignment, std::nullopt,
2679	                                            std::nullopt))
2680	                  .getResult();
2681	
2682	          SmallVector<int64_t> globalShape(rank,
2683	                                           cuda_tile::TensorViewType::kDynamic);
2684	          SmallVector<int64_t> globalStride(
2685	              rank, cuda_tile::TensorViewType::kDynamic);
2686	          // we can always assume the stride is 1
2687	          // because openai has assume this.
2688	          globalStride[globalShape.size() - 1] = 1;
2689	
2690	          auto tensorViewTy = cuda_tile::TensorViewType::get(
2691	              ctx, tileIRPtrType.getPointeeType(), globalShape, globalStride);
2692	          auto makeTensorViewOp = cuda_tile::MakeTensorViewOp::create(
2693	              rewriter, loc, tensorViewTy, ptrWithDivBy, wrappedDynShapes,
2694	              wrappedDynStrides);
2695	
2696	          auto tileShape = descBlock.getShape();
2697	          SmallVector<int32_t> arrayOfi32Shape;
2698	          for (auto i64Shape : tileShape) {
2699	            arrayOfi32Shape.push_back(i64Shape);
2700	          }
2701	
2702	          SmallVector<int32_t> dimMap(rank);
2703	          std::iota(dimMap.begin(), dimMap.end(), 0);
2704	
2705	              auto tilePartViewTy = cuda_tile::PartitionViewType::get(
2706	                  ctx, rewriter.getDenseI32ArrayAttr(arrayOfi32Shape),
2707	                  tensorViewTy, dimMap,
2708	                  cuda_tile::PaddingValueAttr::get(ctx,
2709	                                                   cuda_tile::PaddingValue::zero));
2710	          
2711	              auto partViewOp = cuda_tile::MakePartitionViewOp::create(
2712	                  rewriter, loc, tilePartViewTy, makeTensorViewOp);
2713	          
2714	              auto castBackToTensorDescriptorOp =
2715	                  UnrealizedConversionCastOp::create(rewriter, loc, tensorDescType,
2716	                                                     partViewOp.getResult());
2717	
2718	          rewriter.replaceAllUsesWith(
2719	              tensorDesc, castBackToTensorDescriptorOp.getResult(0));
2720	        }
2721	      }
2722	    }
2723	    return WalkResult::advance();
2724	  });
