2727	/// Convert attributes that are related to the axis analysis.
2728	static void convertAxisAttributes(mlir::ModuleOp op,
2729	                                  ModuleAxisInfoAnalysis &axisInfo,
2730	                                  TypeConverter &converter) {
2731	  SmallVector<Assumption> assumptions;
2732	
2733	  // Find all tt.divisibility, tt.contiguity, tt.constancy attributes. For each
2734	  // such value, do not read the value directly, but query the Triton AxisInfo.
2735	  op->walk([&](Operation *op) {
2736	    if (auto funcOp = dyn_cast<FunctionOpInterface>(op)) {
2737	      // Convert attributes that are attached to function block arguments.
2738	      for (size_t i = 0; i < funcOp.getNumArguments(); i++) {
2739	        auto divByAttr = funcOp.getArgAttr(i, "tt.divisibility");
2740	        auto contAttr = funcOp.getArgAttr(i, "tt.contiguity");
2741	        auto constAttr = funcOp.getArgAttr(i, "tt.constancy");
2742	        if (divByAttr || contAttr || constAttr) {
2743	          Value v = funcOp.getArgument(i);
2744	          assumptions.emplace_back(
2745	              v, *axisInfo.getAxisInfo(v), static_cast<bool>(divByAttr),
2746	              static_cast<bool>(contAttr), static_cast<bool>(constAttr));
2747	        }
2748	      }
2749	      return WalkResult::advance();
2750	    }
2751	
2752	    // Convert attributes that are attached to operations.
2753	    auto divByAttr = op->getDiscardableAttr("tt.divisibility");
2754	    auto contAttr = op->getDiscardableAttr("tt.contiguity");
2755	    auto constAttr = op->getDiscardableAttr("tt.constancy");
2756	    if (divByAttr || contAttr || constAttr) {
2757	      assert(op->getNumResults() == 1 && "expected op with single result");
2758	      Value v = op->getResult(0);
2759	      assumptions.emplace_back(
2760	          v, *axisInfo.getAxisInfo(v), static_cast<bool>(divByAttr),
2761	          static_cast<bool>(contAttr), static_cast<bool>(constAttr));
2762	    }
2763	    return WalkResult::advance();
2764	  });
2765	
2766	  // Now materialize all assumptions as cuda_tile.assume ops. This is not done
2767	  // during the above loop because modifying IR invalidates the axis analysis.
2768	  IRRewriter rewriter(op->getContext());
2769	  for (const auto &assumption : assumptions)
2770	    assumeAxisAttributes(rewriter, converter, assumption);
2771	}
