2776	struct ConvertTritonToCudaTile
2777	    : public ::mlir::triton::impl::ConvertTritonToCudaTileBase<
2778	          ConvertTritonToCudaTile> {
2779	public:
2780	  // Map from load/store operations to num_stages from its parent ForOp.
2781	  DenseMap<Operation *, int> numStagesMap;
2782	  // Value of per-kernel num_stages.
2783	  std::optional<int> numStages;
2784	
2785	  ConvertTritonToCudaTile() = default;
2786	  ConvertTritonToCudaTile(bool approxModifier, bool flushToZeroModifier,
2787	                          int computeCapability, int numCTAInCGA,
2788	                          int simtNumWarpsInCTA, int occupancy,
2789	                          std::optional<int> numStages) {
2790	    this->approxModifier = approxModifier;
2791	    this->flushToZeroModifier = flushToZeroModifier;
2792	    this->computeCapability = computeCapability;
2793	    this->numCTAInCGA = numCTAInCGA;
2794	    this->simtNumWarpsInCTA = simtNumWarpsInCTA;
2795	    this->occupancy = occupancy;
2796	    this->numStages = numStages;
2797	  }
2798	  void runOnOperation() override {
2799	    MLIRContext *context = &getContext();
2800	    ModuleOp mod_buildin = getOperation();
2801	    CudaTileTypeConverter typeConverter;
2802	
2803	    // Insert cuda tile module directly.
2804	    OpBuilder builder(context);
2805	    auto mod = cuda_tile::ModuleOp::create(builder, mod_buildin.getLoc(),
2806	                                           "cuda_tile_module");
2807	    auto &region = mod.getBodyRegion();
2808	    region.getBlocks().clear();
2809	    IRMapping mapping;
2810	    mod_buildin.getBodyRegion().cloneInto(&region, mapping);
2811	    auto &block = mod_buildin.getBodyRegion().front();
2812	    block.clear();
2813	    block.push_front(mod);
2814	
2815	    // Insert Host TMA descriptor ops.
2816	    convertTmaDescriptorOps(mod.getOperation(), typeConverter);
2817	
2818	    ModuleAxisInfoAnalysis axisInfo(mod_buildin);
2819	
2820	    // Check divisibility for all indices in descriptor load and store ops.
2821	    checkDivisibilityForDescriptorOps(mod_buildin, axisInfo);
2822	
2823	    // Convert all axis attributes.
2824	    convertAxisAttributes(mod_buildin, axisInfo, typeConverter);
2825	
2826	    // Get num_stages for load/store ops.
2827	    getNumStages(mod.getOperation(), this->numStagesMap);
2828	
2829	    // Pre-processing: expand tt.map_elementwise into tensor-level ops.
2830	    // This must run before dialect conversion so the expanded arith/math ops
2831	    // get picked up by ConvertGenericOp patterns.
2832	    if (failed(mlir::triton::expandMapElementwiseOps(mod.getOperation())))
2833	      return signalPassFailure();
2834	
2835	    // Dialect conversion: Convert all operations.
2836	    CudaTileConversionTarget target(*context, typeConverter);
2837	    RewritePatternSet patterns(context);
2838	    populateTTirToCudaTileConversionPatternsAndLegality(
2839	        typeConverter, patterns, target, this->approxModifier,
2840	        this->flushToZeroModifier, this->numStagesMap, this->computeCapability,
2841	        this->numCTAInCGA, this->simtNumWarpsInCTA, this->occupancy,
2842	        this->numStages);
2843	
2844	    ConversionConfig config = ConversionConfig();
2845	    config.buildMaterializations = false;
2846	    // use full conversion here to allow only know operations since cuda_tile
2847	    // doesn't allow other dialect's ops
2848	    if (failed(applyFullConversion(mod, target, std::move(patterns), config)))
2849	      return signalPassFailure();
2850	
2851	    // Try to reconcile as many unrealized_conversion_cast ops as possible.
2852	    SmallVector<UnrealizedConversionCastOp> castOps, remainingCastOps;
2853	    mod->walk([&](UnrealizedConversionCastOp op) { castOps.push_back(op); });
2854	    reconcileUnrealizedCasts(castOps, &remainingCastOps);
2855	
2856	    // Required to clean up any remaining unrealized casts and ensure IR
2857	    // validity after dialect conversion. Without this, subsequent passes may
2858	    // fail due to invalid IR structure or unreconciled casts.
2859	    {
2860	      RewritePatternSet patterns(context);
2861	      if (failed(applyPatternsGreedily(mod, std::move(patterns))))
2862	        return signalPassFailure();
2863	    }
2864	  }
2865	};
